/* MxScout — the About & security page.
 *
 * MxScout is meant to live inside a company network, on machines a security
 * team is responsible for. A tool that cannot explain itself gets blocked, so
 * this page is part of the product, not documentation about it: it is the
 * inventory of what MxScout runs, what it touches and what it refuses to do,
 * written to be read by someone who has never seen the code.
 *
 * Two rules keep it honest. It is a DESCRIPTION, not a promise — every claim
 * here must be checkable in the source, so when behaviour changes this text
 * changes in the same commit. And where a control is weak (the non-production
 * guard is a guardrail, not a security boundary) it says so plainly; a
 * reviewer who catches one overstatement rightly distrusts the whole page.
 *
 * It lives in its own file for the same reason it exists: it is the one thing
 * here a person outside the project reads end to end, and it should be
 * findable without scrolling past three thousand lines of UI first.
 *
 * The document is DATA, rendered by block() below. Block kinds:
 *   { p: 'paragraph' }
 *   { ul: ['bullet', …] }
 *   { kv: [['key', 'value'], …] }
 *   { note: 'call-out, for limits and caveats' }
 */
(function () {
  'use strict';

  var el = null;

  function init(api) { el = api.el; }

  function doc(version) {
    return [
      { id: 'what', title: 'What MxScout is', blocks: [
        { p: 'MxScout is a local explorer for a Mendix application model, made for testers and developers. It runs as a small Node.js process on the user’s own machine and shows a UI in their browser. It reads a model either as JSON exported from MxSonar, or directly from a Mendix project folder — the browser reads and decodes the .mpr file itself, no Studio Pro or other tool involved — and, only for development, test and acceptance environments, can connect to a running app to show what a logged-in role really sees.' },
        { p: 'This page exists so it can be handed to a security reviewer. Everything on it is checkable against the source, which ships with the tool.' },
        { p: 'Developer tools are a per-project switch, on that project’s Settings, off by default. Off, a project reads, reviews and documents the model and nothing else: no Live app, no Performance, no Logs, no Comments, no deciding about risks, no MxScaffold drawings, no Security screen (View as on the other screens stays) — and so nothing in it reaches a running app. On, the project shows them, and the Live app and Performance reach a running Mendix app exactly as the sections below describe: through the app tab you connect, and to its admin port on this machine while you record performance. The switch decides what the page shows and lets you start; it is not a build option. The code of every Developer tool, and the server endpoints they use, are in every copy of MxScout, and those endpoints answer whether or not any project has the switch on — each still only after you connect, pair or start a recording yourself.' },
        { kv: [
          ['Version', version ? version + ' (reported by the running server)' : 'unavailable — the local server did not answer'],
          ['Licence', 'GPL-3.0-or-later — the complete source is readable, unminified, with no build step between it and what runs'],
          ['Runtime', 'Node.js, standard library only (http, fs, path, crypto, url)'],
          ['Third-party dependencies', 'None. package.json declares no dependencies; there is no node_modules, no lockfile and no npm install step. One body of third-party SOURCE is in the repository, and is read like the rest: the log analysis in public/logs/ (see “Log analysis” below), written by Mikołaj (RealMecowhy) as MxDevSwissTool, MIT licence, credited in THIRD-PARTY-NOTICES.md. And two fonts, as files rather than code: Instrument Sans and JetBrains Mono in public/fonts/, each under the SIL Open Font License, with its licence text beside it'],
          ['Size', 'About 52,200 lines across 91 files — small enough to read end to end. The test suite ships alongside it in test/, another 127 files and about 22,000 lines that never run as part of the app'],
          ['Install footprint', 'A folder. No installer, no administrator rights, no system service, no scheduled task, no registry or autostart entry, no PATH change'],
          ['Starting it', 'A script in that folder: start.sh, or MxScout.cmd / MxScout.command for a double-click. It runs Node.js on the files already there and opens the browser on 127.0.0.1. On a machine with no Node.js installed, and only after the person typing yes to the question, the launcher downloads the official Node build from nodejs.org into ./runtime — one folder, deleted like any other, no installer and no administrator rights. That is the only thing MxScout ever writes outside the browser, it happens in the launcher and never in the server process, and it never happens without being asked. Answering no, or having no network, leaves the folder untouched'],
          ['Runs as', 'The user who starts it, with that user’s permissions. Nothing is elevated'],
          ['Listening port', 'TCP 4289, bound to 127.0.0.1 only (MXSCOUT_PORT changes the number, never the interface)']
        ] }
      ] },

      { id: 'never', title: 'What MxScout never does', blocks: [
        { p: 'These are not settings. They are properties of the code, and each one is the absence of a capability rather than a switch that could be turned back on.' },
        { ul: [
          'No database connection of any kind — no driver, no connection string, no credentials. MxScout cannot read your app’s database.',
          'Never asks for, stores or transmits an API key or a session cookie. It asks for exactly one password — the Mendix admin port’s, which the runtime mints fresh every time the app starts — and only when you choose to record performance. It is held in the server process’s memory for that session, never written to disk, never logged, never returned by any endpoint, and dropped the moment you disconnect or stop MxScout.',
          'No .mpr parsing on the server, and no Studio Pro or CLI tool involved anywhere. A picked Mendix project folder is read and decoded entirely in the browser, in a Web Worker — see “Reading a Mendix project folder” below.',
          'The server process opens exactly one kind of outbound connection: to a Mendix Runtime admin port, at an address that passed the same non-production guard as everything else MxScout will talk to, asking one of two read-only actions and no third. What bounds it is that allowlist rather than the clock — it happens once when you connect a performance recording, to check the password against that port before keeping it, and then on a loop while a recording runs. It has no other reason to connect and no code that could — see “Reading a running app’s admin port” below for what bounds it. It fetches nothing else, downloads nothing, phones no home and checks for no updates. (The launcher script is a different process, and the one thing it can fetch — a Node.js runtime, only when the machine has none and only when told to — is described under “Starting it” above.)',
          'No telemetry, no analytics, no crash reporting, no licence check.',
          'No external assets — no CDN, no remote fonts, no remote images. The two fonts MxScout uses ship inside it (public/fonts/) and load from this server, and the exported documentation and the team guide (public/guide-team.html) carry them inside the file. The UI renders correctly on a machine with no internet access.',
          'No cookies, no accounts, no login.',
          'The server process writes nothing to disk. Not a log, not a cache, not a temporary file. Exports are ordinary browser downloads the user starts; a project folder, when you choose to keep a project in one, is written by the browser tab itself (see “Where the data lives”), never by the server; and the launcher’s optional ./runtime is written before the server exists, not by it.',
          'No background process and no persistence: close the terminal and the server is gone, along with everything it held in memory.',
          'No git. MxScout never runs a git program and never connects to a git server — not to fetch, not to pull, not to push. For a project kept inside the Mendix project (mxscout/, below) it writes files there, and the people on the team commit, pull and push them themselves, in Studio Pro or a git client.'
        ] }
      ] },

      { id: 'data', title: 'Where the data lives', blocks: [
        { kv: [
          ['Your MxScout folder', 'Only when you choose one — Choose… beside MxScout folder in Settings, or when you import documentation into it: one folder on disk, where MxScout keeps a folder of its own for every project — a project kept in a folder, whole, or, for a project kept in its Mendix project, what is yours and not the team’s (the model’s copy, documentation.md, ai-pack.md, inbox/, assist/), with a project.json naming that project’s id, so an agent finds it from the Mendix project. The browser tab writes it, through the File System Access API, as for a project folder; the server is not involved. The browser keeps the folder (its name, never its path) in its own database and may ask you for permission again after a restart. It is also where the mxscout-project skill reads your projects; that skill learns its path from you, once, and keeps it in ~/.mxscout/library.json on your machine.'],
          ['The project folder', 'Only when you choose one — the first option on New project, “Keep in a folder…” in a project’s menu, or “Move all projects to folders…”: a folder on disk you pick, one per project, anywhere you like. The BROWSER TAB writes it, through the browser’s File System Access API (Chrome and Edge), with the permission the browser asks you for; the server is not involved and writes nothing. It holds project.json (name, source, settings, versions), model.json (the model), descriptions.json (the descriptions, as a descriptions file), assist/ (the Assist items, one file per item in assist/tickets/, jira/, ideas/ and other/ — the workbook), knowledge/ (the solved cases, one Markdown note per case), documentation.md (the documentation as Markdown), ai-pack.md (the AI pack), README.md, comments.json (the comments, as a package carries them), triage.json (what was decided about the risks), and inbox/, where an agent on this machine drops a descriptions file, an Assist file or a solved case’s note that MxScout reads while the project is open and moves to inbox/done/ (the last 20 are kept). Every save in the app rewrites the file it changed; a file someone else changed since — an agent, git, a person — is read back when the project is opened, and the newer one wins (the descriptions with Undo; an Assist item’s file in the place of that item). The browser learns the folder’s name, never its path, and can write only inside the folder you picked. MxScout removes only a file of its own it no longer needs — descriptions.json when you remove the descriptions, comments.json or triage.json when nothing is left in them, an Assist item’s file when Undo takes that item back, a solved case’s note when Undo takes it back — and never a note in knowledge/ it could not take, and never deletes the folder or anything else in it, not even when you delete the project. Not encrypted: the files are as readable as the folder they are in. “Open a project folder…” reads such a folder back in, for instance after git clone on another machine.'],
          ['Inside the Mendix project (mxscout/)', 'Only when you choose it — the first option on New project, “In the Mendix project (mxscout/)”, or when you pick a Mendix project whose mxscout/ a teammate committed, or “Keep in the Mendix project (mxscout/)…” for a project already here (in its menu and on Documentation → Write with Claude — everything it has is written there and it is linked only once all of it is written; a mxscout/ holding another project is never written over, and a folder the project was kept in before is left as it was): MxScout keeps the project in a folder named mxscout/ inside the Mendix project’s own directory, so a team shares the documentation through the app’s own git. The browser tab writes it, through the File System Access API, as for a project folder; the server is not involved. The browser asks you to let the page edit the Mendix project folder you picked — the narrowest grant it offers, since mxscout/ may not be there yet — and MxScout writes inside mxscout/ and, only when you choose it (the default on New project; a switch and “Update the skills in this project” on the Folder tab), the two Claude skills in .claude/skills/mendix-describe/ and .claude/skills/mendix-assist/, where Claude Code loads them so whoever pulls has them — nowhere else in the project, and nothing else in .claude/ (never its settings, never another skill). The .mpr, mprcontents, .git, javasource and everything else are only read (the .mpr and the few .git files, see “Reading a Mendix project folder”), never written. Committed with the app: mxscout.json (the project’s id, its name, the language of written content, the layout, and the commit the descriptions describe — no key, no token, no folder handle, no model version), descriptions/ (the descriptions in small JSON files: app.json, processes/, modules/, risks.json, c4.json, context.json), comments/ (the comments, one file per comment, by the whitelist a package uses) and triage.json (what was decided about the risks) — the team’s knowledge — docs/ (the documentation as Markdown, one file per topic, each with front matter, and manifest.json with every file’s id and SHA-256, the solved cases’ notes among them — written only when the descriptions, the comments, the decisions or the solved cases change, never because the model was read again), knowledge/ (the solved cases: one Markdown note per ticket, Jira issue or idea an agent helped solve, written by the agent and committed with the fix — never personal data; a note with an e-mail address, a phone number or a “Reported by” line in it is neither taken nor listed, and never written over), AGENTS.md, README.md, GUIDE.md and GUIDE.html (the team’s guide, as this MxScout ships it in public/guide-team.md and public/guide-team.html — the page with the stamp as an HTML comment on its second line, so it stays a valid page) and .gitignore. README.md, AGENTS.md, GUIDE.md, GUIDE.html and each skill carry the MxScout version that wrote them (a VERSION file in each skill) and are replaced only by a newer MxScout — a teammate with an older one never downgrades them, and one with the same writes nothing; since 1.18.0 a copy from this MxScout also replaces one an MxScout Dev wrote before the two became one app, never the other way round. AGENTS.md and README.md also tell an agent that does not load skills by itself (Codex, for one) which SKILL.md in .claude/skills/ to read and follow, and suggest one line for the repository’s root AGENTS.md — a line for a person to add: MxScout never writes that file. They, and both skills, also say that an agent writes nothing into the Mendix project but the documentation, and keeps its working files outside it: the skills’ agent.js writes there only descriptions/, docs/, knowledge/, mxscout.json and .local/inbox/ — through its own commands — refuses any other path inside the project (a project folder of its own: only inbox/ and knowledge/), and puts everything an agent makes while it works (packs — the one agent.js makes from the .mpr, kept until the model changes, among them — notes, drafts, files before they are sent, and a copy of each file agent.js replaces or removes there) in a work folder outside it: MXSCOUT_WORK when that is set, else mxscout-work/<project> in the system’s temporary folder. Not committed, and not in the Mendix project at all once you set your MxScout folder (below): model.json (a cache; the .mpr beside it is the truth), documentation.md, ai-pack.md, inbox/ and assist/ are then in a folder of this project’s own there — a mxscout/.local/ from before is copied there, checked, and only then removed. Without an MxScout folder they are in mxscout/.local/, which .gitignore keeps out of git. Performance recordings stay in the browser. A shared file is written only when its text changes, so a teammate who only pulls finds git’s status clean. A JSON file there with git’s conflict markers is shown with both sides and never written over; until one side is kept (or it is resolved in git) MxScout takes nothing from mxscout/ and writes nothing shared. The Assist items and the package key never go into the committed part. Whether Studio Pro’s commit dialog picks up files outside the model is not verified; a git client always does. docs/, knowledge/ and the manifest are what a company pipeline could ingest — each file with front matter, the manifest with its hash, so only what changed need be uploaded; MxScout itself uploads nothing: the committed files are the source.'],
          ['The model', 'The browser’s own database (IndexedDB) for 127.0.0.1:4289 — this machine, this browser profile — and, for a project kept in a folder, model.json in that folder too (in mxscout/.local/, inside the Mendix project). It is never uploaded. The MxScout server does not hold it either — with one exception you start yourself: Share with an agent, below. With it, which version of the application it is, when the Mendix project folder it was read from has a git: the branch, the commit, the commit’s date and the first line of its message, and the last 40 moves of HEAD from the reflog (each a commit, a time and its message) — read from .git as plain files (see “Reading a Mendix project folder”). Never the author’s name or e-mail. Two tabs of MxScout open at once share this database: a save reads the record as the database holds it at that moment and writes it in the same transaction, with a revision number, so one tab never writes its older copy over what the other saved — a comment changed in another tab since this one read it is not saved over, and says so; and the other tabs are told which record moved — through a BroadcastChannel, which reaches only the tabs of this address in this browser and carries the store’s name, the record’s key and its revision, never the record — and read it again.'],
          ['A page of rows read from the app', 'The server process’s memory, in transit between the app tab and the MxScout window. One slot, replaced by the next request, cleared on exit.'],
          ['Live-execution state', 'The same memory: one armed command and its result.'],
          ['Who is signed in to the app', 'The same memory, while the bridge is connected: the user’s name and the names of their user roles, as the bridge reports them when it connects, so MxScout can show what that person reaches. Nothing else about the session. Gone on disconnect, on a new session, or when MxScout stops.'],
          ['Server logs', 'Your terminal, stdout only. Counts, entity and flow names, ok/failed. Never row data, never object ids, never the session token.'],
          ['Documentation you send', 'Only when you choose Export documentation… on the projects page (its ⋯): one file the browser downloads, with the documentation of the projects you tick — each one’s model, descriptions and solved cases, nothing else: no Assist item, no comment, no decision about a risk, no recording, no setting, no package key — encrypted with one access code MxScout shows once and never keeps (AES-GCM, the key from the code by PBKDF2-HMAC-SHA256, as below). Whoever opens it chooses which projects to take; a project that came from such a file remembers which project it was, so a later file updates it rather than adding it twice.'],
          ['Packages you send', 'A file the browser downloads, encrypted with the project’s package key, which travels in it wrapped by an access code MxScout shows once and never stores. It carries the solved cases; it never carries the Assist items. See “The encrypted package” below.'],
          ['Package keys', 'One per project, and only once a package of it was made here or opened here with its access code: a random 256-bit AES-GCM key and a random id, in the browser’s own database (its settings), kept as a WebCrypto key object. It is extractable — that is what lets a later package wrap it again under a new code — so anyone who can read this browser profile can read it, as they can read the project itself. Never in the project folder: not in project.json, not in mxscout/, not in any file there, and the folder is never given it. Never sent anywhere. Settings → Packages → Forget this project’s key deletes it; deleting the project deletes it too.'],
          ['Flow drawings you export', 'A plain .json file the browser downloads, holding the drawing of the microflows you chose — their activities, the arrows between them, and the positions Studio Pro itself stored. It is a handover format for MxScaffold, a separate planning tool, and it is NOT encrypted: it carries project structure, so treat it like any other copy of the model. Nothing is sent anywhere, no connection opens, and the server never sees it — the file is built in the page and handed to the browser’s own download.'],
          ['The AI pack', 'A plain text file the browser downloads when you ask for it: the model’s own modules as the documentation reads them — flows with their steps and the values they set, entities with their members, who may read, write, create and delete them and on which rows, the validation rules that refuse a save, and the widgets on pages and snippets that are shown or editable only on a condition, with the condition — and, when you have marked risks fixed or false positive or raised risks in comments, a short list of them: each risk’s id, level, status, title and places, your reason or note, and the name of whoever raised it. Not encrypted: it is meant for an AI agent on your own machine. MxScout sends it nowhere; where it goes next is up to you — unless you press Share with an agent, which puts it in the server’s memory for that agent to read (next row).'],
          ['Parts for a chat assistant', 'Plain text files the browser downloads when you ask for them, each a few dozen flows of one module, and a prompt you copy to the clipboard. Not encrypted: they carry the model’s structure to whichever assistant you attach them to, so they belong only in an assistant your organisation allows for that. Nothing is sent by MxScout; what you paste back is read in the tab and never reaches the server.'],
          ['The context for a chat assistant', 'The browser’s own database, one small record per project, under settings: the entities, microflows, nanoflows and pages you put aside with + Context or a right-click, by name only, at most 40 — nothing of the model is copied into it. The prompt made of them, with those elements as the AI pack writes them, is copied to the clipboard or downloaded as a plain text file when you press the button: not encrypted, so it belongs only in an assistant your organisation allows for the model’s structure. Nothing is sent by MxScout. The answer you paste back is read in the tab, as JSON, by the same checks as an Assist file, and kept as a workbook item (see “Assist items”). The list is never written to a project folder, a package or an export; Empty the context clears it, and deleting the project deletes it.'],
          ['The shared pack', 'Only after you press Share with an agent in a project’s Documentation: the same AI pack, held in the MxScout server process’s memory so an agent on this machine can read it module by module and send descriptions back, with no file in between. Beside it, when the project has descriptions, the documentation as Markdown — the Markdown copy the export writes, of the own modules, with a short header saying it is what an agent understood earlier, a description whose flow changed since marked out of date — so an agent starts from that and checks it against the pack — and, at its end, the project’s Assist items as a short list (id, kind, title, status, planned date), so the agent knows what is open and what is closed; the tab sends it again whenever the descriptions it keeps change. Both are behind a token the browser tab alone is given, and neither is ever written to disk or logged. Both are dropped when you press Stop sharing, reload or close the tab, or when the server stops. Descriptions the agent sends back — or Assist items: a ticket it checked, a Jira issue or an idea it worked out, or a move of one — wait in memory too, in a queue in the order they came, at most 32 of them and 64 MB in all, until the tab takes them one by one and checks each with the same parser as a file import; a full queue refuses the next one and keeps what waits, and nothing that waits is ever dropped to make room. Then they are saved into the browser’s database at once — a part that adds to what is kept, the first descriptions of a project, or Assist items, which are replaced one by one by their id with their history kept — with Undo beside them; a whole file that would replace descriptions already kept waits until you press Import them. Saving at once can be turned off per project in the same card, and then everything waits for the press.'],
          ['Descriptions you import', 'The browser’s own database, same as the model: the descriptions file an AI agent wrote, one per project, as text — and descriptions.json in the project’s folder, when it is kept in one. Removing them, or deleting the project, deletes the browser’s copy; the folder’s file goes with Remove descriptions, never with deleting the project.'],
          ['Assist items', 'The browser’s own database, same as the model, one record per project: what an agent helped with — tickets it checked against the model, Jira issues and ideas it worked out, and the workbook: larger pieces of work and anything else — each with its status (open, in progress, waiting for the reporter, done, dropped), a planned date when someone set one, the questions to ask the reporter and the conversation with them (append-only: the reporter’s answers you paste, the agent’s replies), the notes you asked the agent to keep on it (what to watch out for and where in the model, each ticked off by you, never removed), the descriptions of the change an agent wrote when you asked (one for the business, one technical — which the page copies to the clipboard or the browser downloads as an HTML or Markdown file, built in this tab and sent nowhere; a workbook item’s technical one with the flows, pages and entities it names as its sources appended, as the model has them), the language it is written in, and its history: who moved it, the person or an agent, and when. When an agent sets the project’s language, it is kept with the project (contentLanguage). A ticket may name the known risk it is about, and that risk lists it. For a project kept in a folder, they are written there too, one file per item (see “The project folder”) — inside the Mendix project, in mxscout/.local/assist/, which git ignores: they are personal and never committed. Otherwise a local base: they are never in a .mxscout package and never in the exported documentation, the HTML file or its Markdown copy. The tickets and changes an older descriptions file carried are moved here when the project is opened. At most 2000 per project: past that, new items are refused, saying so, and none is ever dropped to make room; an item’s file in the folder is removed only when Undo takes that item back. Deleting the project deletes them.'],
          ['Solved cases', 'The browser’s own database, one record per project: the notes an AI agent wrote when a ticket, a Jira issue or an idea was solved — the problem, its cause, the solution, what did not work and how to recognise it next time, with front matter (its id, kind, the flows, entities and pages it is about, keywords, the commit it was checked against) — as text, one Markdown file each. The agent writes them itself, into knowledge/; MxScout writes one only when an agent hands it one (through the agent channel or the folder’s inbox), checked first: a note with an e-mail address, a phone number, an IBAN, a “Reported by” line or a long number in it is refused. For a project kept in a folder they are knowledge/ in that folder — inside the Mendix project, mxscout/knowledge/, committed with the app: the team’s, and the person commits each with its fix. They travel in a .mxscout package; they are in the exported documentation only when you tick “Include solved cases” on Export. MxScout never uploads them anywhere. An agent may hand in at most 2000 per project: past that a new note is refused, saying so, and none kept is dropped to make room. Deleting the project deletes the browser’s copy, never the folder’s files.'],
          ['What you decided about risks', 'The same database, one record per project, apart from the descriptions so an import does not replace it: each risk you marked a false positive (with your reason) or fixed (with your note), who and when, what MxScout found when new descriptions came in, and a copy of the risk as it was last seen. Deleting the project deletes it; removing the descriptions does not.'],
          ['A performance recording', 'The browser’s own database, same as the model. One recording is bounded — ten minutes, or 64 MB of samples, whichever comes first — and one that ended that way says so on itself, so nobody compares a scenario against half of one. While a recording runs, its samples sit in the server’s memory and are handed to the browser when you stop — a recording is never written to disk by the server, and never leaves this machine. The Mendix admin password it needs is read by a tiny PowerShell script you run once per app run, and pasted in by hand; MxScout cannot read it itself. From there it lives in the server process’s memory for this session and nowhere else — not in the browser’s database, not in any file, not in any log, and no endpoint gives it back. Disconnecting, or stopping MxScout, is the end of it.'],
          ['Comments', 'The same database — and comments.json in the project’s folder, when it is kept in one (what was decided about the risks goes to triage.json beside it); inside the Mendix project, mxscout/comments/, one file per comment, and mxscout/triage.json, committed with the app. A comment whose file is gone from mxscout/comments/ after a pull (a teammate deleted it) is deleted here too — unless it was changed here since its file was last written or read; then it is kept and written back. They are the one thing here nobody can regenerate, which is why the export reminder matters — or the folder, in git. A performance recording stays in the browser only.'],
          ['Your preferences', 'The same database: which project was open last, the default language of written content (which every project with no language of its own takes), the name you sign comments with, the theme — light, dark, or the system’s — and, for a project kept in a folder, the browser’s handle to that folder (what lets the tab write it again after a reload), the dates of its own last writes, the files still waiting to be written, and the path you typed for the agent prompt, if you did. Nothing about the app under test.'],
          ['Nothing else', 'MxScout asks the browser to keep that database from being evicted (navigator.storage.persist). That is a request about storage the browser already holds — it grants no new access and reaches nothing outside the page.']
        ] },
        { p: 'The most sensitive thing MxScout ever holds is the page of application data read back from the app under test. It is capped before it is stored — at most 100 rows, 200 fields per row, 500 characters per value — kept in memory, replaced by the next request, never logged and never written to disk. The server log records how many rows came back, never what was in them. The one other thing it can hold is the AI pack you chose to share with an agent — the model’s structure as text, no application data — and, beside it, the documentation as Markdown when the project has descriptions, in the same kind of memory and under the same rules.' }
      ] },

      { id: 'mpr', title: 'Reading a Mendix project folder', blocks: [
        { p: 'A Mendix project file (.mpr) is a SQLite database. MxSonar reads it with sql.js (SQLite compiled to WebAssembly) and the bson npm package; MxScout has neither available, so both are hand-written instead — a page/b-tree reader for the SQLite file (public/sqlite.js) and a decoder for the BSON documents Mendix stores inside it (public/bson.js), together under 500 lines. Both formats Mendix has used are supported: the older one keeps a model document’s full content inline in the project file; the newer one (Studio Pro 10.18 and later) keeps it in a sibling mprcontents folder instead.' },
        { p: 'On a Chromium browser, picking is one step: “choose a Mendix project folder” uses the File System Access API to get a handle to that folder, then reads only what the model actually needs from it — the .mpr file, and, only for a v2-format project, the mprcontents subfolder — and, when the folder has a .git, the few files that say which version it is (below), without ever listing or reading anything else in the project (javasource, themesource, deployment, and everything else Studio Pro puts next to it). Elsewhere, picking is two steps: the .mpr file itself, then — again, only for a v2-format project — that one mprcontents folder, asked for on its own rather than as part of a whole-project scan.' },
        { p: 'The whole parse — reading the SQLite pages, decoding the BSON, building the module/entity/microflow list the rest of the app shows — runs in a Web Worker, off the page’s main thread, and never leaves the browser. The Worker sees the picked files directly; nothing is uploaded, and the MxScout server is not involved at all — it never receives the .mpr file, never receives any file from the project folder, and has no endpoint that could accept one.' },
        { note: 'Which version of the application a model is comes from the Mendix project’s own git, read in the tab as plain files inside the picked folder’s .git: HEAD (the branch, or a detached commit), that branch’s ref under refs/heads or in packed-refs (its commit), the commit object itself when git keeps it loose (inflated with the browser’s DecompressionStream, for the commit’s date and the first line of its message; a packed object is not read), and the last 256 KB of logs/HEAD, the reflog (where HEAD moved, and when). No git program runs, no git server is asked, nothing in .git is written, and of the reflog only the commit, the time and the message are kept — never a name or an e-mail. A .git that is a file pointing elsewhere (a worktree, a submodule) cannot be followed outside the picked folder: the version is then unknown, and the import goes on. So it is with no .git, and with a .mpr picked on its own.' },
        { note: 'A project kept inside the Mendix project (mxscout/) reads its model from the .mpr beside it: when the project is opened, and when you press Re-read, MxScout looks at the .mpr’s size and date and at the commit HEAD names, and when any of them moved it reads the model again — the .mpr is the truth, so it replaces the model without a diff to confirm. A version belongs to the content it was read with: moving a project already here into the Mendix project, its model takes the version git names only when it IS the model in the .mpr there; another snapshot of the same application — the same modules, other content — keeps its own model with its own version, and the status line says the .mpr beside is another snapshot, until Re-read takes it. One line in Documentation says which version the model is and whether the descriptions describe it (“Model main @ f00ba12 · descriptions a1b2c3d (3 flows changed since)”). MxScout pulls nothing: you pull, in Studio Pro or git, then re-read.' },
        { note: 'public/bson.js only decodes — there is no encoder, and none is planned. MxScout never writes a .mpr file; a capability to produce one is not something reading a project needs, and this codebase deliberately does not build it.' },
        { note: 'Three tables live in a .mpr. MxScout reads two of them: Unit, which holds the model, and _MetaData, which says which Studio Pro version wrote the project (shown next to the project name). It does not read, and could not write, the third — _Transaction, the single value Studio Pro uses to notice that something outside it has changed the project. Reading a project leaves no trace in it that a project was read.' },
        { note: 'A property left at its Mendix default is not written to the .mpr at all, so a reader cannot tell “switched off” from “never touched”. MxScout reads such a property as the default Mendix itself would apply, which is the same answer the running app gives — but it means the model is what was SAVED, and unsaved changes in an open Studio Pro are not in it.' },
        { note: 'A Mendix project stores the administrator’s password, and every demo user’s password, in the project file in plain text. The administrator’s is used only when the app runs locally from Studio Pro — every other environment sets its own — so the Security section shows it as set and does not judge it (Karol, 2026-10-15). MxScout opens the passwords in the Worker, long enough to JUDGE the demo users’ ones — against that project’s own password policy, and against a short list of passwords that need no cracking — and then keeps the verdict and drops the value. The Security section says “set, in plain text — weak: 1 character, one of the most common passwords there are, shorter than the 12 characters this project requires”, and no part of MxScout ever holds the password itself: not the model, not this browser’s database, not a .mxscout package, not a printed report. A password that passes leaves nothing behind but “set” — not even its length, which is kept only where the length is itself the finding. Karol’s call, 2026-09-12: “set” alone is hygiene, and the difference between hygiene and a real finding is exactly what an auditor came for.' },
        { note: 'The System module (User, Session, FileDocument, Image, UserRole, Owned) never appears in a project’s own .mpr file — it ships with the Mendix Runtime, not with the project, so there is nothing there to parse. MxScout adds it back as a small, fixed, hard-coded list (public/app.js) rather than pretending to read it from a file that never contains it — it has no attribute data attached for the same reason, though its Data tab still queries a connected app for real rows.' },
        { note: 'That has one consequence worth stating, because it touches the part of MxScout people trust most. A row-level access rule whose path goes through the System module and keeps going cannot be followed here at all — there are no System members in the model to follow it through. Such a rule is marked as unfollowed on the entity popup, with the reason. MxScout does NOT claim it is broken: that a rule like this returns no rows at run time is reported elsewhere and MxScout has not verified it, so the marker says what MxScout could not do and points at the running app, which is the only thing that can answer. The ordinary case — a rule ending at System.owner, the standard “their own rows” idiom — is not marked: it was every single one of the 28 System-touching rules measured across three real projects, and marking it would make the marker meaningless.' },
        { note: 'And when an app is connected, that pointing becomes a button. “Check against the app” asks the running application how many rows the rule’s constraint actually matches, next to how many rows of that entity the session can see at all — because zero matched means nothing on an empty table and everything on a full one. The answer is about the rights of whoever is signed in on that tab, which MxScout is told the user name of and never the role list of, so every answer says so rather than implying the number is the rule’s own population. See “Network behaviour” for the command that carries it and what it cannot carry.' },
        { note: 'What is read out of a project is now its whole tree: the modules, the folders someone made inside them (empty ones included — a folder named “#v1.0.0” is how a team writes down which version of a Marketplace module it took), and every document in them. That last part is wider than what MxScout models: one measured project holds 3,377 documents of 29 kinds, and MxScout models the inside of four of them — microflows, nanoflows, pages and snippets. A page and a snippet are read down to their widgets: the layout a page fills, and in each of its regions the data containers with their entity and where the data comes from, the inputs with the attribute each is bound to, the buttons with what they do, and the conditions under which a widget shows — as text only, no styling, at most 3,000 widgets per document. For the other twenty-five (Java actions, constants, layouts, mappings, …) the model keeps the name, the kind and the folder it sits in, and nothing else: the document is opened once to read its name and to note which flows and pages it mentions, and nothing from inside it is kept. Since the App Explorer was redesigned (2026-10-13) it groups documents by kind and lists only four kinds, so no screen lists those twenty-five today; the model still carries them.' },
        { note: 'A module flagged in the project as coming from the Mendix Marketplace (Studio Pro’s own App Explorer buckets these under “Marketplace modules”) is hidden from every browsing view by default — not just dimmed, entirely absent from the chip row, the lists, the domain model and its entities/microflows/nanoflows/pages — since a security or code review usually cares about the project’s own modules first. Nothing is deleted: a per-project setting (Settings tab) shows them again, and packaging/export always includes the full, unfiltered model regardless of what is currently hidden from view.' }
      ] },

      { id: 'network', title: 'Network behaviour', blocks: [
        { p: 'Three parties can be involved: the MxScout server on loopback, the MxScout tab in the browser, and the tab where the tester already has the app under test open. When you connect a performance recording, and then while it runs, the server also talks to that app’s Mendix Runtime admin port.' },
        { ul: [
          'The server binds 127.0.0.1. It is not reachable from another machine, and there is no option to make it listen on a wider interface.',
          'The server is a passive listener on loopback except for one thing: it calls the admin port of the app under test — once when you connect, to check the password against that port, and then on a loop while a performance recording is running. Nothing else in the server can open a connection.',
          'Requests to your Mendix application are made by the tester’s own browser tab, in their own already-authenticated session: mx.data.get to read rows, mx.data.action to run a flow, and one POST to that app’s own /xas/ endpoint (action retrieve_by_xpath, count: true) — the same call the Mendix client itself makes behind every paged data grid — purely to ask how many rows match. All three are same-origin to the application, carry that person’s own session and CSRF token, and read only. MxScout adds no access path: everything the snippet does is something that same person can do by clicking in the app.',
          'One of those count calls is not about a page of rows: asked for it, the app tab counts how many rows an access rule’s own row-level constraint actually matches. It is the only place MxScout supplies an XPath predicate of its own rather than one the app tab builds from an entity and a search term — that predicate is the rule’s text, out of the project the tester loaded. It rides a command of its own (kind “count”) which is the narrowest on this channel: it carries an entity and a constraint, it has no columns, and it can come back with nothing but two numbers. No row, no value and no object id can travel on it. It exists because whether a rule selects anything is a fact about the running application, and the alternative to asking is guessing.',
          'A row that comes back is also asked, object by object, whether this session may write each of its values — isReadonlyAttr, the same question the Mendix client’s own input widgets ask before they allow editing. That is a question about an object already in hand: it sends nothing, fetches nothing extra, and writes nothing. It is asked per object because a rule’s XPath decides which rows it covers, so the same attribute can be writable on one row and read-only on the next — which is what the green in the Data table means.',
          'Those admin-port calls (server/admin-port.js, the only file in MxScout that can open a socket) go to an address you gave, checked by the same non-production guard as the app itself — local, dev, test and acceptance pass; anything that looks like production is refused before a socket exists. They ask two read-only actions, get_current_runtime_requests and runtime_statistics, and no third one is reachable: the action name is checked against that list rather than passed through, which is what stops this from becoming a way to reach the same API’s shutdown and log-level actions. There are exactly two moments when one of them runs: the password check when you connect, and the sampling loop while a recording is running. Outside those, the server opens no socket at all.',
          'The app tab’s badge carries the record button, so a recording is started and finished where the tester already is. That button reads and asks — nothing more: it never sees the admin port, the password, or a sample. The server does the reading, and the samples go to MxScout’s own window to be saved.',
          'So no traffic leaves the machine at all: the tester’s own browser tabs reach addresses the tester chose, in sessions the tester already holds, and the server’s one outbound connection cannot leave loopback.'
        ] }
      ] },

      { id: 'adminport', title: 'Reading a running app’s admin port', blocks: [
        { p: 'This is the one place MxScout connects outward, so it is written out in full rather than summarised. It exists because the Mendix Runtime’s admin port is the only source of what a performance recording is for: the internal action stack behind a request — which microflow called which, the activity running at that instant, the XPath behind a retrieve. Network traffic does not carry it and the log does not either.' },
        { p: 'A browser tab cannot read that port. The admin API needs a custom authentication header, which makes every call a preflighted cross-origin request, and the port answers no CORS at all. MxScout used to work around that by having you paste a script into a browser tab open on the admin port itself. That worked, and asking someone to paste a script into a console is not obviously the safer thing to be doing, so it is gone: the server makes the call now, under limits written into the code rather than into this page.' },
        { ul: [
          'The address goes through the same non-production guard as the app under test, and the server applies it itself rather than trusting the page that asked: local hosts, and hosts carrying a conventional dev / test / acceptance marker, are allowed. A production-looking address is refused before any socket exists.',
          'Two actions are permitted, both read-only: get_current_runtime_requests and runtime_statistics. The name is matched against that pair rather than forwarded, which is what keeps this from being a route to the same API’s shutdown and log-level actions.',
          'It connects at two moments and no others: once when you connect a recording, to check the password against that port before anything is kept, and then on a loop while a recording runs. Between recordings there is no timer and no socket.',
          'While one is running, the loop asks the port what is executing, waits for the answer, and asks again — never closer together than 10 ms, and never before the previous answer has arrived, so a busy runtime is asked LESS often rather than piled up on. The heavier of the two calls, the runtime-wide statistics, rides along about four times a second instead of on every round. Both are reads; neither can change anything in the app.',
          'A recording stops itself after ten minutes, or once its samples reach 64 MB, whichever comes first — and it says which, on the recording, every time that recording is opened. It does not quietly drop what it collected first: a recording missing its beginning would still look complete, and every count taken from it would be short by an amount nobody could see.',
          'Nothing about the admin port is reachable from another origin. The two endpoints that are cross-origin belong to the record button on the app tab’s badge, are gated on the session token like the rest of that bridge, and can do exactly two things: read whether a recording is running, and ask to start or stop one. Neither carries the address, the password, or any sample.',
          'The password is checked against the port before it is kept, held in the server process’s memory for the session, and returned by nothing. Disconnect forgets it; so does stopping MxScout.'
        ] },
        { note: 'This replaced an earlier promise that the server made no outbound connections at all. The sentence was true and is now narrower, which is why it is stated in one place with its limits rather than repeated as a slogan. server/admin-port.js is about two hundred lines and is the whole of it.' }
      ] },

      { id: 'endpoints', title: 'Every endpoint, and who may reach it', blocks: [
        { kv: [
          ['GET /api/health', 'Name and version. Same-origin only.'],
          ['GET /api/changelog', 'The CHANGELOG.md that ships with this copy, read from disk. Same-origin only. One fixed path, no parameters.'],
          ['GET /api/skills', 'The two Claude skills that ship with this copy — every file of skills/mendix-describe and skills/mendix-assist, named in a fixed allowlist in server/routes/skills.js — read from disk as text, so the tab can write them into a Mendix project’s .claude/skills/ when you choose that. Same-origin only, GET only, no parameters. It writes nothing; the browser writes the project.'],
          ['POST /api/session/start', 'Mints a fresh random session token. Same-origin only.'],
          ['POST · DELETE · GET /api/session/exec', 'Arm or inspect one request to the app, or disconnect: DELETE ends the bridge’s session, so the code pasted into the app tab stops working and the bridge there stops. Same-origin only.'],
          ['GET /api/session/ping', 'The bridge asks whether it can reach MxScout at all, and says who is signed in: a user name and the names of their user roles. Cross-origin, token-gated.'],
          ['GET /api/session/exec/poll', 'The bridge asks whether anything is waiting for it. Cross-origin, token-gated, dispatched at most once. Held open for up to 25 seconds rather than answering immediately, so the app tab reacts at once instead of on a timer.'],
          ['POST /api/session/exec/result', 'The bridge reports how a run went. Cross-origin, token-gated.'],
          ['POST /api/session/data', 'The bridge returns one page of rows it read, each with the ids, the values, and — per row — which of those values this session may write. Cross-origin, token-gated, rebuilt field by field on the server rather than forwarded: values are truncated to a fixed length and the write flags are kept only as true or false, only for columns that actually came back. A “count” command answers on this same channel with no rows at all — two numbers and nothing else.'],
          ['GET /api/session/data', 'The UI collects that page. Same-origin only.'],
          ['POST /api/session/perf/probe', 'Answers the first setup step’s question — is a Mendix admin port at this address? It takes no password, runs the same non-production guard, asks the same read-only runtime_statistics, and keeps nothing: a real admin port refuses an empty password with a 401, and that refusal is the answer. It exists so a wrong address is caught before you run the PowerShell script, not after. Same-origin only.'],
          ['POST /api/session/perf/connect', 'The one endpoint in MxScout that receives a password. You give it an admin-port address; it runs the non-production guard, checks the password against that port before keeping anything, and answers only what it connected to. A password that does not work is never stored. Same-origin only.'],
          ['POST /api/session/perf/disconnect', 'Forgets that password and stops anything running on it. This is how the password leaves memory before MxScout does. Same-origin only.'],
          ['POST /api/agent/share', 'Press Share with an agent, and the browser tab sends the AI pack here, with the documentation as Markdown beside it when the project has descriptions, and the project’s language of written content as a language code (or nothing, while none is chosen). The server checks that the pack is a pack with a readable index and the documentation is MxScout’s, each bounded in size, keeps them in memory, and answers with a token — a new one, unless the request carries the current one, so that replacing the model or changing the descriptions does not cut an agent off. Same-origin only, and refused unless the Host header is 127.0.0.1 or localhost on this port, which is what stops a page that rebinds its own name to this address.'],
          ['DELETE /api/agent/share', 'Stop sharing: the pack, the documentation, the token and anything an agent sent back are dropped. Needs the token. The tab calls it when you press the button and when you leave the page.'],
          ['GET /api/agent/status', 'What is shared, by module with its counts, the language code the agent is to write in, whether there is documentation and how much of it is out of date, the project’s id, and how many results an agent sent that wait for you, the oldest named. Needs the token and the Host check. Same-origin only — the agent has no Origin header, a page in a browser tab does and is refused.'],
          ['GET /api/agent/module', 'One module of the pack, exactly the lines its index gives — the agent’s lazy read. Needs the token.'],
          ['GET /api/agent/pack', 'The whole pack as text, for the checker that compares fingerprints with an earlier descriptions file. Needs the token.'],
          ['GET /api/agent/docs', 'The documentation as Markdown, what an agent reads first; a 404 that says so when the project has no descriptions yet. Needs the token.'],
          ['POST /api/agent/descriptions', 'The agent hands in the descriptions file it wrote, items for the Assist page — an envelope that says "format": "mxscout-assist" — or solved cases, an envelope that says "format": "mxscout-knowledge", for the tab to write into the project’s knowledge/. It must say it is one of the three and is bounded in size; the server does not read it further, apart from two optional text fields it passes on with it: "projectId" (the id the status names — the tab refuses a result for another project) and "snapshot" (the model version the agent read). It is queued in memory with an id of its own, until the tab takes it and checks it with the same parser as a file import; the tab then saves it, or holds it for the press, as “The shared pack” above says. The same text sent again while it waits is not queued twice, nor is a request with the same Idempotency-Key header as one that waits or one of the last 256 taken: the answer names the one already there. A full queue — 32 waiting, or 64 MB in all — answers 429 and keeps what waits. Needs the token.'],
          ['GET /api/agent/inbox · DELETE /api/agent/inbox?id=', 'The tab asks for the oldest result that waits (whole, with how many wait; ?list=1 lists them without their text), and once you have imported or declined it says which one it took, by its id: that one is removed and nothing else — an id taken before, or never sent, removes nothing, and a DELETE that names no id is refused. Need the token.'],
          ['GET /api/session/perf/status', 'The UI asks whether the admin port is connected and recording, how many samples there are, when the recording began, and whether the port has stopped answering. Never includes the password. Same-origin only.'],
          ['POST /api/session/perf/start', 'Starts the sampling loop and clears whatever a previous recording left behind. Refused if no admin port is connected. Same-origin only.'],
          ['POST /api/session/perf/stop', 'Stops the loop and returns everything it collected, so the UI can save it into the browser’s own database. A stop that arrives twice for the same recording answers the same thing twice — a browser re-sending a request whose answer was lost must not be able to turn a recording into an empty one. It also carries the reason, if the recording had already stopped itself at one of its limits. Same-origin only.'],
          ['GET /api/session/perf/poll', 'The record button on the app tab’s badge asks whether an admin port is connected, whether a recording is running, and how many samples it has. Cross-origin, token-gated. It carries no address and no password — only what that button needs to draw itself.'],
          ['POST /api/session/perf/request', 'That same button asking to start or stop — the same change the Start and Finish buttons in MxScout’s own window make. Cross-origin, token-gated. A stop only halts the sampling; the samples are collected by MxScout’s own page through perf/stop above, because only that page can save a recording into its database.']
        ] },
        { p: 'That is the complete list. Anything else under /api answers 404, and every other GET serves one of the static files in public/.' },
        { p: 'Each of the six cross-origin ones also answers OPTIONS — the browser’s own preflight, which carries no token because a preflight cannot carry one: it sets the CORS headers, returns 204, and reaches nothing else. So the route table in server/index.js shows twelve cross-origin entries where this page names six endpoints; the other six are those preflights, and getting past one still leaves the real request needing the token.' },
        { note: 'Rows read out of your application pass through the server on their way from the app tab to the MxScout window, and are held in memory only until the next request replaces them. They are never written to disk and never logged — the log records how many rows came back, never what was in them.' }
      ] },

      { id: 'package', title: 'The encrypted package', blocks: [
        { p: 'A project leaves this browser one way: as a `.mxscout` package, encrypted, opened with an access code that MxScout generates and shows once — the first time. What is protected is the file in transit — mail, chat, a network share.' },
        { kv: [
          ['The project key', 'Each project has one package key: a random 256-bit AES-GCM key from crypto.subtle.generateKey, made by the first package of the project and kept in that browser (“Package keys”, above), with a random 128-bit id that names no project. Every package of the project is encrypted with it, whoever makes it.'],
          ['Encryption', 'AES-256-GCM with the project key and a 12-byte random IV, the key id as additional authenticated data. The authentication tag means a modified file, or a key id moved onto another package, is refused outright; there is no path that shows half a model.'],
          ['Key derivation', 'PBKDF2-HMAC-SHA256, 600,000 iterations, 16-byte random salt — the current OWASP figure — turns the access code into an AES-KW key.'],
          ['Key wrapping', 'The project key travels inside the package wrapped with that AES-KW key (RFC 3394, WebCrypto’s wrapKey). Its integrity check means a wrong code is refused before anything is decrypted.'],
          ['Compression', 'gzip before encryption, via the browser\u2019s own Compression Streams.'],
          ['Access code', '100 bits of entropy from crypto.getRandomValues, in an alphabet without I, L, O or U so it survives being read aloud. Shown once, never stored, not recoverable — a new export mints a new code, wrapping the same project key.'],
          ['Opening one', 'The first package of a project into a browser always needs the code: it unwraps the project key, and that browser keeps the key for the project it opened into. A later package of the same project — its key id matching a key kept here — is decrypted with that key and opens without the code, saying so. A kept key that does not open a package (another key under that id, a key forgotten and made again) is not trusted: MxScout asks for the code. Anyone who made or opened a package of the project keeps the key, so a package made from any of their browsers opens in the others. A package that goes into a project already here first says whether it is newer, older or the same version — by the model’s git commit and its date — and asks before replacing a model with an older one.'],
          ['Older packages', 'A package written before this format (version 1), whose code-derived key encrypts the payload directly, still opens — with its code, every time. A package of a newer format than this MxScout knows is refused with a sentence saying so.'],
          ['Implementation', 'WebCrypto only. No cryptography is written by hand here and no library is pulled in.'],
          ['What is inside', 'The project\u2019s name, its model, the descriptions an AI agent wrote for it (written as a descriptions file, which the receiving MxScout reads with the same checks as an import), and its comments if you tick them, with what was decided about its risks (the decisions about risks raised in comments only with the comments), and its solved cases (their notes, which the receiving MxScout reads by the same rules as one an agent hands it, and writes into knowledge/ when the project is kept in a folder). Not the address of the environment you connected to, and not a performance recording: both came from a running application. Not the Assist items either: they stay in the browser they were made in.']
        ] },
        { p: 'The envelope is JSON rather than an opaque binary blob on purpose, and this page is the reason: open one in a text editor and you can confirm in seconds which algorithms it declares and that no model text is in the clear. The plaintext half carries no application name, no project name and no model version — the file name is the only thing about the contents that travels readable, and it can be changed. The key id is in the clear, because it is what finds the key: it is random and names nothing, but it does show that two packages belong to the same project.' },
        { p: 'A review can also leave as a report rather than as a project. The encrypted HTML report uses the same kind of envelope and access code — in its first format, the payload encrypted with the code-derived key itself and no project key, since the page has only its code to open it with — in one self-contained file that needs nothing but a browser — it renders by building elements from the decrypted data, never by assigning markup. The Word copy is the exception: it is plain content on the clipboard, carries no author, and is not protected at all. MxScout says so on the screen that offers it, because removing the authors does not make a list of an application\u2019s weaknesses safe to circulate.' },
        { p: 'The documentation export is another exception, by choice: one HTML file that opens without an access code, so whoever has it can read the application\u2019s structure and its weak spots. It carries the model as the documentation shows it, not the project — the solved cases only when you tick “Include solved cases” on Export, never the Assist items — and cannot be imported back. The Documentation section says so next to the button that builds it.' },
        { note: 'The encryption protects the file on its way to someone. Once imported, the model, its descriptions and its comments sit unencrypted in that browser\u2019s database, on that person\u2019s own machine. That is a deliberate trade — the threat being addressed is a file travelling by email, not the reader\u2019s own browser profile — and MxScout would rather say so than let it be assumed.' },
        { note: 'The same trade holds for the package key. Someone with access to this browser profile could open later packages of the same project without the code — the same person who can already read the project in that browser. A package someone gets hold of who never opened one of the project still needs its code. To require the code again here, forget the project’s key (Settings → Packages); the next package made from this browser then starts a new key, and everyone else needs the code once more.' }
      ] },

      { id: 'hardening', title: 'Hardening', blocks: [
        { ul: [
          'Content-Security-Policy on every response: default-src \'self\', no remote script, no framing (frame-ancestors \'none\'), base-uri \'none\'. One page has a narrower policy of its own: the team guide, /guide-team.html, a document with its style, its fonts and its one script inside it — default-src \'none\' (it may load nothing, not even from this server), script-src naming that one script by its SHA-256 (the suite checks the hash against the page), its inline style, font-src data:, no framing.',
          'The UI builds every element and sets textContent. One DOM helper does it, and it deliberately offers no markup escape hatch, so nothing inside a model file, a comment or a row of application data can become executable content.',
          'There is exactly ONE place in the whole codebase that assigns markup: the clipboard fallback in public/report.js, which puts MxScout\u2019s own generated, fully escaped HTML into an off-screen node for one tick so that a rich-text copy works in older browsers. It is named here rather than glossed over, and a test fails if a second one ever appears.',
          'The HTML that copy carries is built by the same file, and the only tag it ever derives from something a person typed is a line break: a comment\u2019s paragraph breaks would otherwise collapse when pasted into Word. That happens strictly AFTER escaping \u2014 by then no angle bracket in the string came from the comment \u2014 so it cannot become a way to carry markup out of a comment and into somebody else\u2019s document. Everywhere the comment is shown rather than exported, those breaks are kept by CSS on a plain text node instead, and no markup is built at all.',
          'X-Content-Type-Options: nosniff, X-Frame-Options: DENY and Referrer-Policy: no-referrer on every response.',
          'Static files come from one directory, behind a path-traversal guard, with Cache-Control: no-cache, so a browser never runs an older copy of MxScout than the one on disk. A path that matches nothing answers with a plain 404 page that never repeats the address it was asked for, so the error page cannot reflect anything back.',
          'Request bodies are capped at 64 MB and must carry Content-Type: application/json — which also closes the classic HTML-form CSRF trick that skips the browser’s preflight.',
          'Every route is same-origin only, except the six the app’s own tab must reach. Those are gated on a 128-bit random session token instead.',
          'Anything a browser script sends back is treated as hostile input: the server rebuilds it field by field, bounded in length and count, rather than storing the shape it was handed.'
        ] }
      ] },

      { id: 'token', title: 'Why six endpoints accept cross-origin requests', blocks: [
        { p: 'The bridge is a snippet the tester pastes into the console of the app’s own tab — so everything it sends back to MxScout necessarily comes from that tab’s origin, not from ours. Binding to loopback stops the rest of the network, but not another tab on the same machine.' },
        { p: 'So those six endpoints are gated on a token instead of on the Origin header. The MxScout UI mints a fresh random token immediately before generating a snippet; the snippet carries it and echoes it back, and only a request presenting the current token is accepted. Reconnecting invalidates every snippet generated before it, and a superseded snippet is told so and stops rather than retrying. A website the user happens to have open cannot guess the value, and therefore cannot plant fabricated data or steer a run.' }
      ] },

      { id: 'prod', title: 'The non-production guard', blocks: [
        { p: 'Before MxScout will connect to a running app, the address is classified, and only clearly non-production environments are allowed through:' },
        { ul: [
          'Local hosts — localhost, 127.0.0.1, ::1, *.local, *.localhost — are allowed.',
          'A host carrying a conventional non-production marker as a whole dot- or dash-separated label is allowed: dev, development, test, testing, tst, accept, acceptance, acc, acp, accp, sandbox, staging, stage, uat, qa, local.',
          'Everything else is refused: a bare *.mendixcloud.com, a company domain, an address on the LAN, anything that is not http(s), anything unparseable.',
          'Markers are matched as whole tokens, never as substrings, so a host like account.company.com is not mistaken for an acc environment.',
          'The same check is re-embedded in the generated snippet and runs against the tab it was pasted into — so it holds where it matters, not only in the UI. An automated check compares the two copies of the list before every release, because a difference between them would otherwise be silent.'
        ] },
        { note: 'Stated plainly: this is a guardrail against mistakes, not a security boundary. MxScout is open source, so a determined developer can edit the check out. Its job is to stop a tester from pointing a read or a run at production by accident. It is not, and is not claimed to be, a control that would stop someone who intends to.' }
      ] },

      { id: 'exec', title: 'Live execution — the two things that can change data', blocks: [
        { p: 'MxScout can trigger a microflow or nanoflow in the connected app tab, and it can create a temporary (non-persistable) object there — the second exists because a non-persistable entity has no database row to browse, so testing a flow that takes one as input means creating a fresh one first. If either writes, deletes or sends something, that really happens — in the tester’s own session, with exactly the rights they already have. Everything else in MxScout is read-only, including looking up an object by an id the tester already knows: that is a plain read, same as browsing any other entity.' },
        { p: 'The same panel says what reaches the flow when no role can set it off: another flow, a page’s button, a scheduled event, a published REST operation, an entity event, App Settings (the after-startup, before-shutdown and health-check microflows). That is worked out by reading every document in the project for the names it mentions, in this browser, and it is why a flow that nothing at all reaches can be shown as exactly that rather than as “called from other logic”. Java code is not read, so a flow only a Java action calls is the one case it cannot see, and the documentation’s Model quality says so. A model imported before MxScout read call sites says it does not know, rather than claiming nothing reaches anything.' },
        { p: 'Because that button is the one thing here that is not read-only, the window it sits in says what the flow does before it is pressed — in a band across the top, on whichever tab is open. Whether it reads, creates, changes, commits or deletes, and which entities; whether it calls a Java action or reaches outside the app; and whether it does any of that inside a loop. All of it is read out of the flow’s own body in the model, in this browser, and it is a summary of activities, not an interpretation: a flow that writes says so whether or not it is named as if it does.' },
        { p: 'Both are wrapped the same way:' },
        { ul: [
          'Refused outright on anything the guard above does not classify as a development, test or acceptance environment.',
          'Reading data, looking up an object by id, running a flow, and creating an object all travel the same channel but are validated separately: a read or a lookup carries no parameters and no values, and nothing on the server turns one into a write.',
          'A flow’s inputs are validated by shape before they leave: object inputs must be plain numeric object ids, and typed-in values are bounded and coerced to a string, a finite number or a boolean — the server holds no model of the running app’s entities, so that is as far as checking a parameter can honestly go, and it says so rather than implying more.',
          'An object input may carry attribute values to set on it before the run. The bridge applies them to the loaded object as uncommitted changes (obj.set) and hands it to the flow — the flow sees the values, but nothing is written to the database unless the flow itself commits. The values are validated the same way a created object’s are, and the confirmation names each one.',
          'Anything a search or a parameter puts into an XPath expression — the field being searched, the attributes an untargeted search covers — must be a plain identifier, checked on the server before the bridge builds the expression. The term itself is compared by the chosen field’s own type rather than pasted into a text match, and a term that cannot mean anything for that field matches nothing instead of quietly matching everything.',
          'The user must acknowledge a warning each time a project is opened, before either running a flow or creating an object is offered. The acknowledgment is never remembered — not across reloads, not across projects.',
          'Every run or create needs a confirmation naming the exact flow and the exact objects and typed-in values, or the exact entity and the exact values about to be set.',
          'Arming is same-origin only; the server validates the shape, and the UI only ever offers flows and entities that exist in the loaded model.',
          'A command is dispatched to the bridge exactly once — a retried poll can never run the same flow (or the same create) twice — and a result for a stale or unknown command id is discarded.',
          'The bridge shows a badge in the app tab for as long as it is connected, with an ✕ that stops it.'
        ] },
        { p: 'One thing MxScout watches but never initiates: while the bridge is connected, it wraps the app’s own mx.data.action read-only and notes which object ids the app’s microflow calls carry. This is the only way to point at a temporary (non-persistable) object — it has no store to list from — without a tester copying an id out of the console by hand. It is observation, not access: nothing here starts a call, reads a cookie or a token, or touches anything the tester’s own clicks did not already send; the noted ids stay in the app tab’s memory, bounded, and leave it only when MxScout explicitly asks for them, offered back as plain lookups the tester could already do by id.' }
      ] },

      { id: 'updates', title: 'Versions and updates', blocks: [
        { p: 'MxScout does not check whether a newer version exists. Not on startup, not behind a button, not at all. Three reasons, in order of weight:' },
        { ul: [
          'A version check would mean connecting to somewhere other than this machine, and the promise above — that nothing MxScout does reaches past loopback — is the single sentence a review remembers. It is worth more than the convenience.',
          'Inside a corporate network the check would usually fail anyway, so an automatic one would mostly greet the user with an error MxScout caused itself.',
          'MxScout has no write access to its own directory and should not have any. An application that downloads and overwrites its own files is the pattern most often blocked, and rightly.'
        ] },
        { p: 'What it does instead: it tells you exactly which version is running — read from the server rather than from a constant, so it cannot claim a version it is not — and shows you what is in that version, from the CHANGELOG.md that ships inside the copy you are running.' },
        { p: 'It also notices when the version has CHANGED since you last used it, and shows you what you moved onto. That needs no network: the fact lives in this browser. It is the "there is a new version, here is what changed" moment, arriving when the update actually happened rather than when a remote server was asked about one.' },
        { kv: [
          ['Finding out whether a newer one exists', 'You look at the repository. MxScout does not.'],
          ['Moving to it', 'A person runs the update script in the MxScout directory — update.sh, or Update.cmd on Windows, or start.sh --update — which runs git pull --ff-only against the repository that copy was cloned from and leaves a copy with changes of its own as it is; or the person replaces the directory. The app never runs it, never runs git, and never rewrites its own files.'],
          ['Source of truth', 'The version field in package.json, served by /api/health.']
        ] }
      ] },

      { id: 'logs', title: 'Log analysis', blocks: [
        { p: 'Log analysis in the sidebar reads a Mendix application’s log in one viewer: the stream with its filters and a records-over-time chart, Insights (one card per problem that actually occurs), the slow queries the runtime reported. It is the one part of MxScout that was not written here: the analysis comes from MxDevSwissTool by Mikołaj (RealMecowhy), https://github.com/RealMecowhy/MxDevSwissTool, MIT licence, Copyright (c) 2026 Mikołaj. The licence text and a file-by-file list of what was carried over, what was changed and what was left out are in THIRD-PARTY-NOTICES.md at the root of the repository, and every ported file names its origin in its first lines. The screens over it are MxScout’s own.' },
        { ul: [
          'A log never reaches the server. A file you pick, drop or paste is read in this tab — large ones in a Web Worker, which is a file of its own under public/logs/, served from the same origin like everything else, because the Content-Security-Policy allows no other kind — and what it produces stays in this tab’s memory. Nothing is written to disk, to the browser’s database or to localStorage; closing the tab forgets it. No endpoint was added.',
          'It makes no request at all. The original’s charting libraries are not carried over — the chart is drawn directly as SVG — so no code is fetched and none is added from outside.',
          'It builds the screen with the same DOM helpers as the rest of MxScout. Text from a log is only ever set as text, and a SQL statement is shown as spans built from the engine’s tokens, so nothing in a log can become markup. The “exactly ONE place assigns markup” statement in Hardening still holds across public/logs/ and is checked by the test suite.',
          'What leaves the screen leaves only when you ask, and only to you: Export filtered is a text file the browser downloads, with the filtered lines as they are. Nothing is put on the clipboard.',
          'The original carries more tools than this — a Query Extractor, Microflow Tracer, REST & WS Extractor, Error Decoder, Nginx analyzer, Anonymizer and Incident Report. MxScout carried them over and, on 2026-10-09, took them out again, to keep the section to what a tester reads a log for. The Error Decoder’s rules stay inside Insights, which groups errors by the mechanism they name.',
          'It is a section of the project (Logs, in the project’s own list) and also works with no project open, under Tools. Inside a project it reads the log against that project’s model, in this tab: a warning or error that names a microflow, nanoflow, page or entity — or a PostgreSQL table (shop$order), which is resolved to its entity (Shop.Order) — shows that object, opens it over the log, and “Report” starts a comment on it with the log lines already written in. Nothing is saved until you save that comment, and then it is an ordinary comment in this browser’s own database. Nothing about the model leaves the tab, and no log text goes into the model.',
          'The original’s own test assertions for every part that is still carried run against the ported code in the suite, so a drift from how the original reads a log fails there.'
        ] }
      ] },

      { id: 'source', title: 'Reading the source', blocks: [
        { p: '67 entries below, 91 files, no build step. What runs is what you read. The largest, docs-view.js, is under 3,000 lines. Four directories in the repository are not in this list because none of what is in them runs as part of the app: test/, which is there to be read and run yourself, .github/, one workflow that has GitHub run that suite on its own machines — Windows, Linux and macOS — for every push, with GitHub’s own checkout and setup-node actions and nothing else installed, tools/, one dependency-free Node script, build-guide.js, run by hand to make public/guide-team.html from public/guide-team.md (the suite checks the committed page is exactly what it makes), and skills/, folders of Markdown and dependency-free Node scripts for a coding agent (mendix-assist, which writes Assist items and solved cases’ notes, checks them with its own check-assist.js and runs mendix-describe’s tools beside it; mendix-change-proposal; mendix-describe; and mxscout-project, which picks a project from the person’s library of MxScout projects and loads its documentation), which the app never loads and never calls — with two scripts beside them, install.sh and install.ps1, that a person runs by hand to put mendix-describe, mendix-assist and mxscout-project into their own ~/.claude/skills/ — with --codex (-Codex on Windows) into Codex’s skill folders as well — ~/.agents/skills/, where Codex looks now, and ~/.codex/skills/ ($CODEX_HOME/skills/ when that is set), which it still reads — and with --codex-only (-CodexOnly) there alone — (a link or a copy; any other folder of that name is moved to the skills-backup/ folder beside it, never deleted), and that MxScout never runs. mendix-describe carries byte-identical copies of eleven of the files below in its engine/ (the suite checks they are), and repodocs.js beside them, so its agent.js reads a .mpr and writes mxscout/docs/ exactly as MxScout would — with the comments and what was decided about the risks — for a team that works with an agent alone. One of them, mendix-describe’s agent.js, is the agent’s side of the agent channel: it calls this server on loopback, with the token you gave the agent, and refuses any other address.' },
        { kv: [
          ['server/index.js', 'The whole HTTP server: loopback bind, security headers, the same-origin gate, the route table, static files — the team guide among them, with its own narrower policy.'],
          ['server/routes/session.js', 'Every endpoint listed above, with its validation.'],
          ['server/routes/skills.js', 'GET /api/skills: the Claude skills that ship with this copy, read-only, from a fixed allowlist of files in skills/ (the test suite checks it against the disk), for the tab to write into a Mendix project’s .claude/skills/. Reads, never writes.'],
          ['server/routes/agent.js', 'The agent channel: the AI pack you chose to share, held in memory, read module by module by an agent on this machine with a token, the documentation as Markdown beside it when there are descriptions, and the descriptions it sends back, held in memory until the tab fetches them. Its header says who may call and what is deliberately not done with the pack; the endpoints are listed above.'],
          ['server/state.js', 'All server state — the session token, the one command in flight and its answer, the admin-port connection including the password, the recording’s sample buffer, and the AI pack while you share it with an agent, with the documentation beside it. Every one of them is a module variable in one process, and nothing else is held anywhere.'],
          ['server/http-util.js', 'Body reading: the size cap and the JSON content-type gate.'],
          ['public/app.js', 'The shell: state, projects, the browsing views, the header the other sections share (their name, the search, the project menu — View as is on the four screens it narrows, which draw their own), and what each other file is given. A screen that fails to draw says what broke and offers a way back, instead of going blank.'],
          ['public/dialog.js', 'Every window over the screen a modal dialog, for the keyboard and for a screen reader: it gives each one role="dialog", aria-modal and a name (its title), moves the focus inside when it opens, keeps Tab inside it, closes it on Escape when the window says how, and puts the focus back on what opened it. It sets those three attributes and moves focus — it stores nothing and reaches nothing.'],
          ['public/objects.js', 'The two object popups — an entity on Attributes & access (one matrix of its members, attributes and the associations it owns, against the access rules that apply) / Data / Comments, a flow on Run (inputs, who may set it off, and what it does when set off, side by side) / Comments.'],
          ['public/accessrule.js', 'One row-level access rule: the readable rendering of its XPath, and the judgement of whether MxScout could follow it at all. The same walk does both on purpose, so the picture and the warning can never disagree. Split out of objects.js because two screens ask — the access matrix, one rule per column, and the Security section, which counts the rules MxScout could not follow so nobody has to open every entity to find them.'],
          ['public/security.js', 'The Security section: the project’s own Security screen as the file records it — which of the three security levels the app runs at, whether it allows anonymous visitors and as which role, demo accounts, the password policy, and the roles, user and module, in one place. Also the two things no role filter can answer: what the app publishes to the outside (REST, OData, web services — each with its own role list and its own authentication, neither of which goes through the access rules) and what runs on a timer with nobody signed in. It opens on the settings as tiles — the security level, anonymous access, strict mode, the page URL check, the password policy — and under them what to act on; then the accounts beside the roles, what is open to the outside and what runs with nobody signed in. It assigns no score: it orders what it found and never grades it. It renders what MxScout CONCLUDED about a password — weak, and why, measured against that project’s own policy — and never the password: the reader judges each one in the Worker and drops the value before a model is built. It names no entity and no flow: it says how many entities have notes on their access rules, and the notes themselves — every user role’s entity access set against what that role can reach (see accessuse.js), and the rules MxScout could not follow — are in each rule’s Access window on the Domain model, marked as worth knowing unless a flow fails for a role.'],
          ['public/accessuse.js', 'Entity access measured against what uses it, from the model alone: for each user role, every rule it holds is set against the pages it may open (with the snippets on them), the flows it may call and the flows those call. Five things come out: a rule that reads every row of an entity where nothing the role reaches lists them all; a rule nothing the role reaches uses; a write, create or delete right nothing it reaches uses; a nanoflow or a microflow that applies entity access, which the role can run, doing what the role has no right to; and a microflow that skips entity access doing for the role what its own rules forbid. Per user role, not per module role, because a page and a rule in two different modules are joined only by the user role that carries both. A user role a published OData service is open to is named and left out, since which entity an OData set hands out is not read here. What it finds is shown at the entity it is about, in the Access window of the rule on the Domain model. Nothing runs, nothing is sent: it is arithmetic over the model already in this browser.'],
          ['public/live.js', 'Everything about talking to a running application: the non-production guard the UI consults, the session, the connection, reading rows, and running a flow. It also turns an enumeration value into the caption a user would see — the app answers with the stored key, and the caption comes from the model in this browser, with the key kept on the cell.'],
          ['public/perf.js', 'The performance recording, browser side: the tiny PowerShell script that only reveals the admin password, the three setup steps, Start/Finish, a dashboard of saved recordings, and an analyzer (Overview / Timeline / Call tree / Hotspots tabs) for one of them — the Overview separates what the runtime counted itself (the database operations) from what the sampler caught (microflow and retrieve counts, which are a floor, never a tally), the Timeline stretches to as many pixels per second as you ask for and scrolls, and carries the runtime’s heap and database counters on the same ruler as the requests, all of it computed in this browser from samples already in its own database — the same comments.js findings every object popup uses, reachable from a Hotspots row. A name anywhere in the analyzer opens that entity or microflow in its own popup OVER the recording, so reading one costs nothing: closing it puts you back on the same tab, the same zoom and the same picked call. Recordings can be exported to a JSON file and imported back from one; import is a file read in this tab and a row written to this browser’s database, with no admin port, no server round trip and no network of any kind. It never talks to the admin port itself — it cannot, and the reason is in “Reading a running app’s admin port” above.'],
          ['public/bridge.js', 'The one snippet pasted into the app tab, written as ordinary code and serialized when it is generated — so what the tester pastes is a file you can read here, not a string assembled at runtime. It also draws the corner badge, including the record button that starts and finishes a performance recording without leaving the app.'],
          ['server/admin-port.js', 'The only file in MxScout that can open an outbound connection, and the shortest way to check every claim on this page about that: the loopback-only address list, the two-action allowlist, the password check that runs once when you connect, and the sampling loop that runs while a recording does.'],
          ['public/store.js', 'Every persistent read and write, and nothing else does storage. The browser’s own database — a change read, made and written in one transaction on the record as it is then, with a revision number, and the other tabs of this address told which record moved (BroadcastChannel) — and — for a project kept in a folder — that folder too, written after the database (write-through), through folder.js: what is pending when the folder cannot be written, what changed there since its own last write, the inbox. Inside the Mendix project: what is shared in mxscout/ apart from what stays in mxscout/.local/, a shared file written only when its text changes, docs/ only when what it is made from does (the solved cases among it), a solved case’s note never over a file there it could not take, nothing shared while git left a conflict. No server.'],
          ['public/folder.js', 'The project folder as a backend, through the browser’s File System Access API: picking a folder, asking the browser for permission to write it, reading and writing its files (a file is written beside the old one and swapped in whole; a model in pieces, so the page is never held up; a file written with CRLF, as git on Windows may leave it, is read as LF), the inbox and inbox/done/, and what each file holds — with Developer tools on also comments.json and triage.json. It writes only when store.js says so. A test hook lets the suite hand in a folder of the browser’s private file system instead of a picked one; nothing in the app sets it.'],
          ['public/repodocs.js', 'A project kept inside the Mendix project (mxscout/), as files: what mxscout.json, README.md, AGENTS.md and .gitignore say; the descriptions split into small files and joined back, exactly; the documentation’s Markdown split by topic into docs/, each file with front matter, and the manifest with their SHA-256 (WebCrypto); git’s conflict markers and both sides of them; and a solved case’s note in knowledge/ — read from its front matter and sections, checked (personal data among it), listed in docs/index.md and in the manifest. Pure — it reads and writes nothing itself — and it runs in Node too with the documentation engine, so a tool that reads a .mpr writes byte-identical files: the mendix-describe skill carries a copy, and mendix-assist’s checker reads a note with it.'],
          ['public/repoui.js', 'A project kept inside the Mendix project, as screens: keeping a new project there, moving a project already here into it (Keep in the Mendix project (mxscout/)…: written whole first, linked last; the same project there linked to it; another project there never written over; the same application — most of its modules — kept apart from the same snapshot — the same content — so a model never takes another snapshot’s version), opening one a teammate committed (the model from the .mpr beside it, the descriptions, comments and decisions from mxscout/, the same project in this browser linked to it), reading the model again when the .mpr changed, the status line with Re-read, and keeping one side of a file git left in conflict. It never runs git and writes no file itself.'],
          ['public/guide-team.md · public/guide-team.html', 'The team’s guide, in English and Polish. guide-team.md is the text, which MxScout writes into mxscout/GUIDE.md for a project kept inside the Mendix project. guide-team.html is the same guide as one page, made from it by tools/build-guide.js and committed: MxScout serves it at /guide-team.html (Help → Team guide, at the foot of the sidebar, and on Getting started, open it in a new tab), writes it into mxscout/GUIDE.html beside GUIDE.md, and anyone can download it from the public MxScout repository. It is a document, not part of the app: its stylesheet, the two fonts (as data: URIs) and its one script — the language switch, which sets text and classes only and keeps the choice in the address, not in storage — are inside it. It loads nothing and stores nothing, and it is served with a policy of its own (Hardening, above). Both are read by the tab like any other file here.'],
          ['public/folderui.js', 'Keeping projects in folders, as dialogs: where a new project or an opened package is kept (a folder first, this browser second), Keep in a folder…, Open a project folder… (with what to do when this browser already has that project), Move all projects to folders… with its progress, and Reconnect the folder when the browser needs your permission again; and what someone else changed in a project’s folder, taken in when the project is opened (the folder wins — the descriptions with Undo, the comments merged by id, the decisions about risks per risk). It writes no file itself.'],
          ['public/crypto.js', 'The package format, the project’s package key (made, wrapped by the access code, unwrapped) and the access code. WebCrypto only — no hand-written cryptography, no library.'],
          ['public/transfer.js', 'How a project leaves this browser and how one arrives: the whitelist of what may travel, the project’s package key (made with the first package, kept, reused, tried before the code is asked for, forgotten on request), the dialogs — what a package holds, and which is newer when it goes into a project already here — and the merge back into storage, into the folder chosen for it too, when a package is opened as a new project.'],
          ['public/sqlite.js', 'A hand-written SQLite page/b-tree reader — the .mpr file itself is a SQLite database. Decode-only, no SQL engine, one table at a time.'],
          ['public/bson.js', 'A hand-written decoder for the BSON documents Mendix stores inside a .mpr. Decode-only.'],
          ['public/mpr.js', 'Turns a decoded .mpr Unit table into the same model shape a JSON import produces — including where every page’s and snippet’s data comes from (the database, with or without an XPath, an association, the object in context, a microflow or a nanoflow), what its inputs edit and its New and Delete buttons act on, how each retrieve in a flow reads and which attributes each of its create and change actions sets, which is what the Security section measures entity access against. For every activity it also keeps the settings Studio Pro’s properties dialog shows where the file holds them — the variable it makes, commit and refresh, events, a retrieve’s range and sorting, whether a call keeps its result — for the step inspector and the Studio Pro view. And each entity’s validation rules — required, unique, a range, a regular expression, a maximum length, equal to — with the message a user sees, for the AI pack.'],
          ['public/mprWorker.js', 'Runs sqlite.js, bson.js and mpr.js in a Web Worker, off the page’s main thread.'],
          ['public/mprImport.js', 'Picking a Mendix project — one folder pick on Chromium via the File System Access API, or the .mpr file plus its mprcontents folder if the format needs one — the progress dialog, and handing the finished model to app.js, with the version it is; replacing a project’s model, the objects added and removed, by name — saying that changes inside an object are not compared there; and, for a project kept inside the Mendix project, reading it again with no dialog.'],
          ['public/modelversion.js', 'Which version of the application a model is, from the Mendix project’s own git, read as plain files inside the picked folder’s .git — HEAD, a ref or packed-refs, the commit when it is stored loose, the end of the reflog — with no git program and nothing written; the stamp kept with the model, without names or e-mails; how it reads (“main @ a1b2c3d · 14 Oct 2026 · “Fix order status””); which of two versions is newer; and the commits between two of them, from the reflog.'],
          ['public/explorer.css', 'The look every screen of MxScout shares: the header with the search and View as, the segments, the inspector’s sections and links — the stylesheet the App Explorer screen started; that screen is gone (its flow details are on the Microflows screen), its styles are what the others are built from. The exported documentation carries it for its flow screen.'],
          ['public/flowgraph.js · public/flowgraph.css', 'A microflow or nanoflow drawn as a graph, DRAKON-style — the Workflow view of the Microflows screen, its default: the main path straight down the page, the other way out of a decision leaving from the node to the right, every step a card with its family’s colour and icon. Self-contained, so it travels inside the exported documentation.'],
          ['public/flowview.js', 'One flow, read the way a developer reads it — the component behind both the Microflows screen and the exported documentation’s Microflows, Nanoflows and Pages: the list of names with its triage and the flow in one of two views behind a switch: Workflow, the default — drawn top to bottom, a variable traced through it, the step and the flow as a whole in the panel beside it — and Modeler — drawn as Studio Pro keeps it, a step’s window with its properties dialog, the flow as a whole behind About; and for a page, the page drawn by pagepreview.js across the whole width, zoomed and scrolled as the Modeler is, with what was clicked on it — or, behind About this page, its details and what opens it — in a window over it. It works on the documentation’s own entries and reaches nothing of the app’s — no storage, no server, no other screen — so the exported file carries it as it is, with flowgraph.js, flowtrace.js, studioview.js and pagepreview.js and their stylesheets. Each shell hands it what to list and what its buttons do: the app adds Run… and Add comment, the file only Copy link. Every node is built with createElement and every text set as text.'],
          ['public/domain.js', 'The Entities screen: the documentation reader’s Domain model page on its own (docs-view.js, mounted for that one page, on the data the Documentation section builds), one module at a time, Own or Marketplace (the whole model, as App Explorer reads it) — nothing picked on arrival, the whole module drawn, a click on an entity greys the ones not linked to it, a click beside them lets go; an access rule’s read and write open that role’s access member by member, and its XPath reads as a path — with the app’s own actions on the entity: Browse data, which shows its rows in the connected app alone — search, paging, a row’s details — in a dialog of this screen’s style; Add comment; and, when it has comments, a link to them. View as narrows it to the entities the chosen role reaches — an entity with an access rule for one of that role’s module roles — and their associations. It reads the model and writes nothing.'],
          ['public/pagepreview.js · public/pagepreview.css', 'A page drawn the way Studio Pro’s page editor draws it, for the Pages screen and the exported documentation: the layout as a frame (a pop-up window, or a page with a header and a menu) and every widget as what it is — a labelled field with the attribute’s name in grey, a drop-down with its arrow, a date picker with its calendar, buttons in their Studio Pro style, tabs that switch, layout grid columns side by side, a list as its item and two faded repeats, a snippet in place inside a dotted outline, and a small amber eye on whatever shows only on a condition. Nothing code-like is drawn: a click on an element says in words what it shows, where its data comes from, what it does and when it is visible, with the model’s own names, XPath and expressions under For developers, and offers the way to a flow or page it opens. It draws the widget tree mpr.js reads for each page and works on the documentation’s own entries, reaching nothing of the app’s; every node is built with createElement and every text set as text.'],
          ['public/microflows.js · public/microflows.css', 'The Microflows screen, the Nanoflows one and the Pages one — MxScout’s shell around flowview.js: the header with the search, View as and the project’s menu, the flows the chosen role may run, and the app’s own actions. What it shows: with nothing picked yet, the modules first, each with how many flows it holds and how many carry a risk; then the list with its triage (with risks, no callers), the flow drawn, a variable traced through it (where it is set, changed, read, committed, deleted and returned), the step you click with every detail of its action — the members a Create or Change object sets grouped by where their values come from, a member a risk names flagged — and the flow as a whole: who may start it, what it calls, what calls it, its risks — beside the drawing, or under it on a screen too narrow for both. Run… opens the window that runs it against a connected app. That window — also where a flow opens as an aside from a recording, the log, Security or the search — has the same graph on its Flow tab, with a button to this screen; App Explorer’s Open microflow comes straight here. Read from the model, except the description and the risks an agent wrote, shown only when you imported them and marked as the agent’s.'],
          ['public/flowtrace.js', 'What a flow does with its variables, worked out from the drawn workflow alone: which variables it has, where each is set, changed, read, committed, deleted and returned, a sentence for each and for each step, the members of a Create or Change object grouped by source, and which way of a decision stays on the main path of the drawing. It draws nothing; the screen, the graph and the Studio Pro view all read the same answers.'],
          ['public/studioview.js · public/studioview.css', 'The Studio Pro view: the flow drawn as the model keeps it — every object at the place and size Studio Pro stored, inside a loop from the loop’s corner, each line leaving and entering by the side the model records, zoomable — or, for a model that carries no positions, laid out left to right as Studio Pro lays it out, outputs under each activity and parameters above, the merge drawn; the variables the picked step uses and the steps that use its output marked, and under it, beside what the step inspector says about that step, its properties dialog, read-only — every field Studio Pro shows, with “[not read yet]” where the model does not hold one — and a button to what the step works on: the flow it calls, or the entity it creates, changes or retrieves, when the model holds one.'],
          ['public/exchange.js', 'The flow-drawing handover file for MxScaffold: the translation from Mendix’s own names into that tool’s vocabulary, and the compaction. A pure transform — no network, no storage, no dependencies.'],
          ['public/comments.js', 'Comments: writing them (in a dialog in the middle of the screen) — one may be marked as a risk, P1 to P3, and then shows on the Risks page and beside its object as raised by its author — the “Comments · N” link to an object’s own, filtering them, the history that records when one was marked fixed, the whitelist that decides what leaves in a package, and the rule by which two copies of one comment reconcile.'],
          ['public/report.js', 'The two report outputs — the clipboard copy for Word, and the standalone encrypted HTML file. Also the one place in the codebase that assigns markup, named in Hardening above.'],
          ['public/docs-data.js · public/docs-view.js · public/docs-triage.js · public/docs-file.js · public/docs.js', 'The Documentation section and the file it builds (put together by docs-file.js, which also runs in Node, so a tool that reads a .mpr itself can build the same file from these same files): everything the model says about itself — modules, every microflow, nanoflow and page (each flow drawn as the Microflows screen draws it, with the same step inspector, trace and Studio Pro view; a page with its details and what opens it), the domain model, one module drawn at a time — the layout worked out here, with no layout library: the entities on a grid, the associations as lines that run between the boxes — and each entity with its attributes, its associations and who may read, write, create and delete it, and where the model looks unfinished. You choose which modules go into the file; the Marketplace ones start unticked. It is read out of the model (docs-data.js), drawn by one reader (docs-view.js), and made in the section (docs.js), which says what the file holds, shows previews that are that same reader drawn small, and builds it. The reader is one self-contained function: the previews run it in the app, and the export carries that very function — and, for Microflows & pages, the very files the Microflows screen runs (flowview.js, flowgraph.js, flowtrace.js, studioview.js and their stylesheets), read from this server unchanged — so the file shows what the app shows. The export is one HTML file, not encrypted — whoever has it can read it — built in this browser, handed to the browser’s own download, sent nowhere. The same documentation also comes as one Markdown file, the drawings as tables and lists and a flow with no risk, description or process as one line: the reader writes it, from the section here or from a button inside the HTML file itself, offline, from the file’s own data, again handed to the browser’s download and sent nowhere. The one other place it goes is the agent channel, and only while you share: the Markdown of the own modules, with a header saying what it is (docs-file.js), held in the server’s memory beside the pack (see “The shared pack”). It is the project’s documentation, not the tool’s: its mark is the project’s first letter, its title the project’s name, and it names no tool. Every page has its own address inside the file (#/flows/Module.Name?step=3, #/domain/Module/Entity …), so a link to one opens that page — a flow with the step it names picked — and Copy link copies it. Search everything (Ctrl K) looks through the file’s own data, in the file: the names of modules, processes, flows, pages, entities and risks, then the words an agent wrote; each result goes to that page’s address. Nothing it is asked leaves the page. Rebuilt from the model every time one is loaded; it reads the model and writes nothing. The same pages are also MxScout’s own screens — Overview, Processes, Modules, Architecture, Risks, Model quality and For developers in the sidebar — mounted from that one reader, with a link on them opening the app’s screen for what it names; and one page only MxScout has, Assist (next entry), which the reader draws only when MxScout hands it the items, so the exported file has no such page. On the Risks page, where each risk stands in the risk triage — its status, who raised it, what was decided and its history, the filter by status — is drawn by docs-triage.js, a file of its own that the reader hands what it draws with, and that the exported file carries beside the flow screen’s files; and in MxScout a risk lists the tickets on the Assist page that say they are about it.'],
          ['public/knowledge.js · public/docs-knowledge.js', 'The solved cases. knowledge.js keeps them: one record per project in the browser’s database, through store.js, each a note an agent wrote in knowledge/ as text; it reads what an agent hands in — an envelope with "format": "mxscout-knowledge" through the agent channel, or the .md note left in the folder’s inbox — checked by repodocs.js’s rules (the five sections, the file’s name against its id, and personal data: a note with any is refused whole), saved at once with Undo; it takes what the folder holds that is newer, and a note removed there; and it hands the notes to a package and back. MxScout records no case of its own: there is no button for it. docs-knowledge.js draws the Solved cases page from the documentation reader: every case in a list with a search and a filter by kind, one opened as text — its simple Markdown drawn as elements, never parsed as markup — the flows and pages it names linked to their place, and “may be out of date” when one of them changed since (its fingerprint moved) or is gone. An Assist item whose solution is a case shows “In the documentation”, linking to it. The exported file carries this file and the cases only when you tick “Include solved cases” on Export.'],
          ['public/assist.js · public/docs-assist.js · public/docs-tickets.js · public/docs-changes.js', 'The Assist page: what an agent helped with, in four tabs — Tickets (a ticket checked against the model: a bug, as designed, data or configuration, or cannot tell, with the evidence, a reply to paste back, and the known risk it is about, linked on the Risks page), Jira (an issue worked out from the model), Ideas (a change someone wants: how it works now beside the proposal, and the model changes) and Other. Each tab a list with a search and a status filter; each item with its status — open, in progress, waiting for the reporter, done, dropped — a planned date, its questions for the reporter (Copy questions puts the open ones on the clipboard, nothing is sent), the conversation with the reporter, to which you add their answer, and a history of who moved it and when. assist.js keeps them: one record per project in the browser’s database, through store.js; it reads what an agent hands in (an envelope with "format": "mxscout-assist", by the agent channel or Import descriptions…) as text, bounded, replacing an item by its id and appending to its history and its conversation, never losing them — or, for an entry marked "update", merging only what changed, and refusing the whole file when an update names an item this project does not keep; it moves the tickets and changes an older descriptions file carried onto the page, once. docs-assist.js draws the page, from the documentation reader, with the ticket’s parts (docs-tickets.js) and a change’s (docs-changes.js). Nothing of it is in a .mxscout package or in the exported documentation; the agent reads the items as a short list at the end of the documentation it is given while you share.'],
          ['public/reportdata.js', 'The values the documentation’s pages work out from its data — each risk’s theme, which module uses which and the order the dependency matrix lists them in, the role matrix, the model-quality checks, the modules each developer note names, the processes with the risks that touch them, each module’s contents and domain model. Ported from the redesign’s reference implementation and held to its output by a test; computed when the file is built and carried in it, so the reader only draws them.'],
          ['public/docs.css', 'The Documentation section’s styling, scoped entirely under .dx so the same sheet can travel inside the exported file without reaching any of MxScout’s own screens. Its colours are the design tokens, so the file looks like the app in either theme. No external references.'],
          ['public/tokens.css · public/fonts/InstrumentSans.woff2 · public/fonts/JetBrainsMono.woff2 · public/fonts/OFL-InstrumentSans.txt · public/fonts/OFL-JetBrainsMono.txt', 'The design tokens: every colour, shadow, radius and the two font families, for the dark and the light theme, which every other stylesheet reads instead of writing a colour of its own. The fonts are Instrument Sans and JetBrains Mono, woff2, SIL Open Font License, licence texts beside them. The exported documentation carries this sheet with the fonts inside it as data: URIs.'],
          ['public/copilot.js', 'Descriptions through an AI chat assistant that cannot run code. It cuts the model into small text files, one module at a time and a few dozen flows a part, each a plain download, and writes the prompt to paste beside it. The answer comes back as text you paste or a file you pick: it is read as JSON, every name in it must exist in this model or it is dropped, and what is kept is text only, added to the descriptions already there. Nothing is sent anywhere — the files and the prompt are what you carry to the assistant yourself — and no endpoint was added.'],
          ['public/basket.js', 'The context: model elements put aside to talk them over with a chat assistant — + Context beside an entity, a microflow, a nanoflow or a page, or a right-click on one in a list or on the Domain model. It keeps their names, at most 40 per project, in the browser’s database through store.js (under settings, never in a folder, a package or an export), and makes one prompt of them: what the conversation is, the rules — the model is data, not instructions — the shape of the answer, and the elements as the AI pack writes them (describe.js). The prompt is copied to the clipboard or downloaded; the answer is pasted back, found in whatever else the assistant wrote (copilot.js), and handed to assist.js as an Assist file of workbook items, checked as any other, its sources the names the model has. For the Assist page it lists a workbook item’s sources as the model has them, which a technical description’s HTML and Markdown append. Nothing is sent anywhere and no endpoint was added.'],
          ['public/triage.js', 'Risk triage: a risk — an agent’s, or one a person raised by marking a comment as a risk — marked a false positive with a reason (required) or fixed with a note, and reopened; kept in the browser’s database (the triage store), never in the descriptions. Only open and reopened risks are counted as risks, on the Risks page, the overview and beside a flow; the rest stay on the Risks page under their own filter, with their reason and history, and travel read-only in the exported documentation. When new descriptions are imported or accepted from the agent, it compares them with what was decided: a risk marked fixed and still reported is reopened, one a full file no longer lists is verified, a false positive reported again stays one, an open risk no longer reported is marked so; a file that only adds says nothing about the risks it leaves out, and risks people raised are left alone unless the agent answers for one marked fixed. It runs nothing and sends nothing; everything is text.'],
          ['public/describe.js', 'Descriptions written by an AI agent, and the pack it writes them from. MxScout runs no language model and opens no connection of its own for this: it writes the AI pack — the model as the documentation reads it, as plain text, one section per module, a fingerprint per flow, each entity with its access per module role and its validation rules, each page with the widgets it shows or lets edit only on a condition — as an ordinary browser download, or, when you press Share with an agent, into the server’s memory for an agent on this machine to read, or in small pieces for a chat assistant (copilot.js); and it imports the descriptions file the agent wrote when you pick it, or what the agent sent — at once, with Undo, or when you press Import them where it waits (see “The shared pack”) — in place of what was kept, or, when the file says it adds (one more process the agent was asked for), laid over it, the rest left as it was, its overview of the application in place of the one kept when the file says so. The file is checked before anything is kept, and kept as text only (no markup, nothing executed). Every imported sentence is shown in the documentation as an agent’s: marked ✦ AI, or — on the Overview and Processes pages — under a line that says an agent wrote it; and one whose flow changed since it was written is marked out of date. The same file may carry the risks the agent ranked P1 to P3 and notes for developers, each with its own page in the documentation, also marked ✦ AI; notes on a module, which sit on the module’s page; and the architecture it drew — the context and the containers as nodes and links, which MxScout lays out itself (the context’s groups around the application, the runtime’s parts in one frame between who calls in and what they call), with how the modules depend on one another, as a matrix, and which user roles reach which module, both read from the model, beside it. Who uses the application may come as groups, each a name and a sentence. A process that branches may carry a simplified diagram — steps, decisions with their ways, ends — which the Processes page draws as the Microflows screen draws a flow, as text. A file written before the Assist page existed may still carry changes the person asked an agent to work out and tickets it checked against the model: they are moved to the Assist page (see public/assist.js above) — an agent’s proposal and an agent’s judgement, kept as text, applied to nothing. MxScout sends nothing to a tracker: a ticket’s source address is kept and shown as text, never opened, linked or fetched, and a reply is copied to the clipboard only when you press its button. A page exists only when the file carries what it shows. Everything of it is kept as text, bounded, and a link to a node that is not there is dropped. Marketplace modules are left out of the pack.'],
          ['public/timeline.js', 'The performance Timeline: one time axis, the tracks drawn on it, and the panel for whatever is picked. It reads no samples of its own — every number it draws is handed to it by perf.js.'],
          ['public/version.js', 'Which version is running, what is in it, and the reasoning for not checking whether a newer one exists.'],
          ['public/devtools.js', 'Developer tools, the per-project switch: whether a project has them on (project.devTools, off by default), the card on its Settings, and the sections it shows. It hides and shows; it deletes nothing, and it is not a build option — every Developer tool’s code and the server’s endpoints are in every copy.'],
          ['public/theme.js', 'Light, dark, or the system’s: the choice at the foot of the sidebar, kept in the browser’s own database with the other settings, and set on the page as an attribute the stylesheet keys on. Nothing else.'],
          ['public/settings.js', 'Settings: one screen, in two sections said to be what they are — Project settings, for the open project: where it is kept first (in words, with the other places it can go), its name and language (the global default named beside it), Developer tools, its Claude skills, its package key, its Marketplace modules; and Global settings, for every project: the MxScout folder, the default language, the theme, your name. Each row is written by the module that owns it.'],
          ['public/home.js', 'The projects page, where MxScout opens and where the logo leads: a card for each project with its Mendix version, its numbers and where it is kept — this browser only, a folder of its own, your MxScout folder, or its Mendix project (mxscout/) — said in words with what that means for Claude; its actions behind ⋯; a search over the projects; Set up MxScout once (the MxScout folder and the language Claude writes in) until both are chosen or it is put away; and the global settings in a line. It reads what store.js and folderui.js say; it writes nothing itself but whether the set-up card was put away, in the browser’s settings.'],
          ['public/bundle.js', 'Export documentation… and its import: the documentation of the projects you pick — for each, its model, its descriptions and its solved cases, from a whitelist, and nothing else — in one file encrypted with one access code, shown once and never kept (crypto.js, the code-only envelope); and, opening such a file, the list of its projects, each new, an update of one that came from an earlier file, or up to date, and only the ticked ones taken. It writes no file itself: the browser downloads the one it makes.'],
          ['public/about.js', 'This page. It is data — a list of sections and blocks — rendered by one function that only ever sets text.'],
          ['public/guide.js', 'The Getting started walkthrough. Same shape as this page — data, rendered by one function that only sets text — but every mockup on it is built from the real component classes the actual screens use, against a fictional project.'],
          ['public/palette.js', 'The search (Ctrl K, or /): a name typed shows what it found grouped by kind — modules, microflows, nanoflows, pages, entities, places to go — best match first, the match marked, case and accents ignored; a / walks projects, sections and modules instead. The matching and the keyboard. It searches the model in this browser and sends nothing anywhere.'],
          ['public/logs/engine/parser.js · public/logs/engine/sql.js · public/logs/engine/insights.js · public/logs/engine/decoder.js', 'Log analysis, the part that reads: the Mendix log parser (Studio Pro CSV, Cloud live, on-premises, Grafana), the SQL tokenizer and highlighter, the extraction and aggregation behind Insights and the slow queries, and the error rules Insights groups errors by. MxDevSwissTool’s code (Mikołaj / RealMecowhy, MIT) carried over unchanged, with a header on each file saying so. Pure functions — no DOM, no network, no storage.'],
          ['public/logs/parse-worker.js', 'The Web Worker that parses a large log off the page’s main thread — a few lines, loading the parser above from the same origin. It has no access to the page and opens no connection.'],
          ['public/logs/ui/core.js · public/logs/ui/widgets.js · public/logs/ui/index.js', 'The Log analysis screen’s foundation, written for MxScout: the DOM helpers and shared state, the tabs, dialogs, toasts and file pickers, the chips that link a log line to the model, and the frame around the viewer.'],
          ['public/logs/ui/viewer.js · public/logs/ui/viewer-analysis.js', 'The Log Viewer: the stream, its filters, the records-over-time chart, bookmarks and the context menu — and the Insights, Slow queries and error-signature views built on the original’s analysis.'],
          ['public/logs/logs.css', 'The Log analysis screen’s styling, on the same tokens as the rest of MxScout. No external references.'],
          ['public/index.html · public/styles.css', 'The page shell and its styling. No external references.']
        ] }
      ] },

      { id: 'faq', title: 'Questions a review usually asks', blocks: [
        { kv: [
          ['Does it need internet access?', 'No. It works on a machine with no route out. The app under test is reached by the tester’s own browser, and the one connection MxScout itself makes — to that app’s admin port while recording performance — goes wherever you pointed it, which the non-production guard limits to local, test and acceptance addresses.'],
          ['Does it need administrator rights?', 'No. It is started by the user and runs with that user’s permissions.'],
          ['Does it open a port other machines can reach?', 'No. It listens on TCP 4289 on the loopback interface only.'],
          ['Does it handle credentials?', 'One, and only if you record performance: the Mendix admin port’s password, which the runtime mints fresh every time the app starts. You paste it in; it stays in the server process’s memory for that session, is never written down anywhere, and no endpoint returns it. Everything else relies on a session the tester has already established in their own browser — MxScout never sees an application password, a token or a session cookie. The secrets it creates are a package’s access code, which it shows once and does not keep, and a project’s package key, kept in this browser so later packages of the project open without the code (“Package keys”, above).'],
          ['Can it reach production?', 'It refuses by design (see the guard above), and that refusal is repeated inside every generated script. It is a guardrail against accidents, not a control against intent.'],
          ['What could leak if the machine were compromised?', 'Only what is already in that browser, and in the project folders you chose: the model, the comments, the Assist items, any saved performance recordings and the package keys of the projects packed or opened there (which open later packages of those projects) in its own database, and — if a page of data was just read, or a performance recording is in progress — at most a hundred rows, or that recording’s samples, in the server process’s memory, cleared on the next request or on Finish. While an admin port is connected, its password is in that memory too, until you disconnect. Nothing is on disk and nothing is sent anywhere. All of it is already readable by anyone who has that machine and that browser profile.'],
          ['Can it modify our application?', 'Only through running a flow, above: one the tester opens and runs in their own session, with their own rights, on a non-production environment, after two explicit confirmations that name the flow and the object. Reading data cannot write: a read request carries no object parameters and there is no path that turns one into a run.'],
          ['Is the code auditable?', 'Yes. No dependencies, no minification, no bundler, no obfuscation — around 47,700 readable lines under GPL-3.0-or-later.'],
          ['Does it read files from my disk?', 'Only a Mendix project folder you explicitly pick, and only in the browser tab — the .mpr file and its BSON documents are parsed client-side, in a Web Worker (see “Reading a Mendix project folder” above). The MxScout server process never sees that folder or any file in it, nor a project folder you chose, which the browser tab reads and writes inside that folder only — only, if you press Share with an agent, the AI pack MxScout builds from the parsed model, and the documentation as Markdown beside it.'],
          ['Is any of it tested?', 'Yes \u2014 an automated suite runs before every commit, needing no dependencies either: Node\u2019s standard library and the Chromium already on the machine, nothing else. It covers the environment guard (including that its two copies still agree), the whole bridge in a real browser, the encrypted package and every way it must refuse, and the round trip of sending a review out and importing it back, every window used with the keyboard alone, and the claims on this page that can be counted. It ships with the app, in test/, and runs with npm test \u2014 so this answer can be checked rather than taken on trust. Nothing reaches this branch without passing it first, and GitHub runs it again for every push, on Windows, Linux and macOS (.github/workflows/test.yml).'],
          ['What happens when it is closed?', 'The process exits and its memory goes with it. Projects stay in the browser’s own database until the user deletes them or clears site data, and in the project folders the user chose until the user deletes those.'],
          ['Does it change anything on the machine?', 'It installs nothing, registers nothing, and the server writes no files. The browser tab writes one thing, and only when you choose it: a project folder you picked — or mxscout/ inside the Mendix project you picked, and, if you chose it, the two Claude skills in its .claude/skills/ — through the browser’s own File System Access API, inside that folder and nowhere else. The scripts in skills/ that install the three skills on a person’s own machine are run by that person, never by MxScout, and write only ~/.claude/skills/mendix-describe, mendix-assist and mxscout-project (and ~/.claude/skills-backup/) — and, only with --codex or --codex-only (-Codex, -CodexOnly), the same three in Codex’s ~/.agents/skills/ and ~/.codex/skills/ ($CODEX_HOME/skills/ when that is set), each with its skills-backup/ beside it.'],
          ['Does it touch our git repository?', 'Only if you keep a project inside the Mendix project: then it writes files in mxscout/ there — and, if you chose it, the two Claude skills in .claude/skills/mendix-describe/ and .claude/skills/mendix-assist/ — which you commit like any other file. It never runs git, never commits, pulls or pushes, never writes anything in .git (it reads a few files there to name the version), and never connects to a git server.']
        ] }
      ] }
    ];
  }

  function block(b) {
    if (b.p) return el('p', { class: 'about-p', text: b.p });
    if (b.note) return el('p', { class: 'about-note', text: b.note });
    if (b.ul) {
      return el('ul', { class: 'about-ul' }, b.ul.map(function (item) {
        return el('li', { text: item });
      }));
    }
    if (b.kv) {
      return el('div', { class: 'about-kv' }, b.kv.map(function (pair) {
        return el('div', { class: 'about-kv-row' }, [
          el('div', { class: 'about-kv-key', text: pair[0] }),
          el('div', { class: 'about-kv-val', text: pair[1] })
        ]);
      }));
    }
    return null;
  }

  function render(version) {
    var sections = doc(version);

    var toc = el('nav', { class: 'about-toc' }, sections.map(function (section) {
      return el('a', { class: 'about-toc-link', href: '#about-' + section.id, text: section.title });
    }));

    var rendered = sections.map(function (section) {
      return el('section', { class: 'about-section', id: 'about-' + section.id }, [
        el('h3', { class: 'about-h', text: section.title })
      ].concat(section.blocks.map(block).filter(Boolean)));
    });

    return el('div', { class: 'about' }, [
      el('div', { class: 'about-head' }, [
        el('div', {}, [
          el('h2', { class: 'about-title', text: 'How MxScout works, and what it touches' }),
          el('p', { class: 'muted', text: 'Written for a security review. Every claim here is checkable in the source that ships with the tool.' })
        ]),
        // A reviewer usually wants this as an attachment, and printing to PDF
        // is the one way to produce that without MxScout gaining the ability
        // to write files or send anything anywhere.
        el('button', {
          class: 'btn btn-sm about-print', text: 'Print / save as PDF',
          onclick: function () { window.print(); }
        })
      ]),
      toc
    ].concat(rendered));
  }

  window.MxAbout = { init: init, doc: doc, block: block, render: render };
})();
